INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$1d9a09c0$SATQ$, $SATQ$415fe94c-ab61-423e-be12-248420d84c52$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Jason Reynolds&rsquo;s 2016 novel <em>Ghost</em>. The narrator, who is in middle school, is at a bus stop.</p>
<blockquote>
<p>I just go there [to the bus stop] to look at the people working out. See, the gym across the street has this big window&mdash;like the whole wall is a window&mdash;and they have those machines that make you feel like you walking up steps and so everybody just be facing the bus stop, looking all crazy like they&rsquo;re about to pass out. And trust me, there ain&rsquo;t nothing funnier than that. So I check that out for a little while like it&rsquo;s some kind of movie: <em>The About to Pass Out Show</em>, starring stair-stepper person one through ten.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2016 by Jason Reynolds</span></p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"35d2e592-3093-40df-bbd8-ac5ec1d9915f","content":"<p>To give a reason why the narrator is excited to start middle school</p>"},{"id":"e8fe0be7-4237-4a97-9540-c0a110e4cde2","content":"<p>To describe an activity that the narrator finds amusing</p>"},{"id":"8f9d5a6c-ef4e-44de-a127-d93f7fe432da","content":"<p>To explain a problem that the narrator has overcome</p>"},{"id":"8ba7e6ad-5837-498f-9792-67a860fb5a94","content":"<p>To discuss a movie that the narrator saw in a theater</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e8fe0be7-4237-4a97-9540-c0a110e4cde2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the main purpose of the text. The text describes how the narrator watches people working out at a gym through a window near a bus stop. The narrator says that "there ain&rsquo;t nothing funnier" than watching people try to work out on the stair climber machine. Thus, the main purpose of the text is to describe an activity that the narrator finds amusing.</p><p>Choice A is incorrect because the text isn&rsquo;t about the narrator beginning middle school. The text describes how the narrator finds people working out at a gym amusing and makes no mention of school life. Choice C is incorrect because the text doesn&rsquo;t mention any problems that the narrator currently has or has overcome. It just describes how the narrator finds watching people work out amusing. Choice D is incorrect because the narrator invents the made-up movie mentioned in the text. The text doesn&rsquo;t indicate that the narrator has seen a movie in a theater. The focus of the text is on the narrator watching people at the gym, not watching a movie.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1d9a09c0","external_id":"415fe94c-ab61-423e-be12-248420d84c52","vaultid":null,"uId":"b0090b4e-4876-4e24-98f7-1f24465a1e5e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Jason Reynolds&rsquo;s 2016 novel <em>Ghost</em>. The narrator, who is in middle school, is at a bus stop.</p>\n<blockquote>\n<p>I just go there [to the bus stop] to look at the people working out. See, the gym across the street has this big window&mdash;like the whole wall is a window&mdash;and they have those machines that make you feel like you walking up steps and so everybody just be facing the bus stop, looking all crazy like they&rsquo;re about to pass out. And trust me, there ain&rsquo;t nothing funnier than that. So I check that out for a little while like it&rsquo;s some kind of movie: <em>The About to Pass Out Show</em>, starring stair-stepper person one through ten.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2016 by Jason Reynolds</span></p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"35d2e592-3093-40df-bbd8-ac5ec1d9915f","content":"<p>To give a reason why the narrator is excited to start middle school</p>"},{"id":"e8fe0be7-4237-4a97-9540-c0a110e4cde2","content":"<p>To describe an activity that the narrator finds amusing</p>"},{"id":"8f9d5a6c-ef4e-44de-a127-d93f7fe432da","content":"<p>To explain a problem that the narrator has overcome</p>"},{"id":"8ba7e6ad-5837-498f-9792-67a860fb5a94","content":"<p>To discuss a movie that the narrator saw in a theater</p>"}],"keys":["e8fe0be7-4237-4a97-9540-c0a110e4cde2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the main purpose of the text. The text describes how the narrator watches people working out at a gym through a window near a bus stop. The narrator says that \"there ain&rsquo;t nothing funnier\" than watching people try to work out on the stair climber machine. Thus, the main purpose of the text is to describe an activity that the narrator finds amusing.</p><p>Choice A is incorrect because the text isn&rsquo;t about the narrator beginning middle school. The text describes how the narrator finds people working out at a gym amusing and makes no mention of school life. Choice C is incorrect because the text doesn&rsquo;t mention any problems that the narrator currently has or has overcome. It just describes how the narrator finds watching people work out amusing. Choice D is incorrect because the narrator invents the made-up movie mentioned in the text. The text doesn&rsquo;t indicate that the narrator has seen a movie in a theater. The focus of the text is on the narrator watching people at the gym, not watching a movie.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323041,"updateDate":1730147323041}$SATQ$::jsonb, 1730147323041, 1730147323041),
    ($SATQ$1f2d6173$SATQ$, $SATQ$77d9e3c0-d312-40eb-a54b-06a3589a4335$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Scholarly accounts of the Chicano movement&mdash;a movement that advocated for the social, political, and cultural empowerment of Mexican Americans and reached its zenith in the 1960s and 1970s&mdash;<span role="region" aria-label="Referenced Content"><u>tend to focus on the most militant, outspoken figures in the movement</u></span>, making it seem uniformly radical. Geographer Juan Herrera has shown, however, that if we shift our focus toward the way the movement manifested in comparatively low-profile neighborhood institutions and projects, we see participants espousing an array of political orientations and approaches to community activism.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"c6f1f694-14a8-4087-a765-57e620aef1cc","content":"<p>It presents a trend in scholarship on the Chicano movement that the text claims has been reevaluated by researchers in light of Herrera&rsquo;s work on the movement&rsquo;s participants.&nbsp;</p>"},{"id":"c817d594-3710-4f6b-acfa-be0afbe30b2e","content":"<p>It identifies an aspect of the Chicano movement that the text implies was overemphasized by scholars due to their own political orientations.&nbsp;</p>"},{"id":"f12eba5b-3532-4323-b5d0-0a34b5ed1909","content":"<p>It describes a common approach to studying the Chicano movement that, according to the text, obscures the ideological diversity of the movement&rsquo;s participants.&nbsp;</p>"},{"id":"7326a6ad-0805-4f6f-ac8b-1e3ff6facb6e","content":"<p>It summarizes the conventional method for analyzing the Chicano movement, which the text suggests creates a misleading impression of the effectiveness of neighborhood institutions and projects.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f12eba5b-3532-4323-b5d0-0a34b5ed1909"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text begins by mentioning scholarly accounts of the Chicano movement, which the underlined portion describes as tending "to focus on the most militant, outspoken figures in the movement," making the movement as a whole seem uniformly radical. The text then indicates that the work of geographer Juan Herrera shows that focusing less on such militant figures and instead paying more attention to manifestations of the Chicano movement in less widely known neighborhood institutions and projects would reveal that the movement&rsquo;s participants embraced a range of political orientations and approaches. Thus, the underlined portion describes a common approach to studying the Chicano movement that, according to the text, obscures the ideological diversity of the movement&rsquo;s participants.</p><p>Choice A is incorrect. Though the underlined portion does present a trend in scholarship on the Chicano movement, the text does not indicate that other scholars have reevaluated their methods in light of Herrera&rsquo;s work. It only indicates that Herrera&rsquo;s work suggests that the work of those other scholars does not provide a complete picture of the Chicano movement. Choice B is incorrect. Though the underlined portion does identify an aspect of the Chicano movement that the text indicates has been overemphasized, the text does not discuss the political orientations of the scholars whose work is mentioned in the text. Choice D is incorrect. Though the underlined portion does summarize the conventional method for analyzing the Chicano movement, the rest of the text does not address the effectiveness of "comparatively low-profile neighborhood institutions and projects." Instead, the text suggests that those projects were led by people with a variety of approaches to community activism.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1f2d6173","external_id":"77d9e3c0-d312-40eb-a54b-06a3589a4335","vaultid":null,"uId":"b8ed217a-9630-41e6-ad8d-68c20e8669d8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Scholarly accounts of the Chicano movement&mdash;a movement that advocated for the social, political, and cultural empowerment of Mexican Americans and reached its zenith in the 1960s and 1970s&mdash;<span role=\"region\" aria-label=\"Referenced Content\"><u>tend to focus on the most militant, outspoken figures in the movement</u></span>, making it seem uniformly radical. Geographer Juan Herrera has shown, however, that if we shift our focus toward the way the movement manifested in comparatively low-profile neighborhood institutions and projects, we see participants espousing an array of political orientations and approaches to community activism.</p>","stem":"<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"c6f1f694-14a8-4087-a765-57e620aef1cc","content":"<p>It presents a trend in scholarship on the Chicano movement that the text claims has been reevaluated by researchers in light of Herrera&rsquo;s work on the movement&rsquo;s participants.&nbsp;</p>"},{"id":"c817d594-3710-4f6b-acfa-be0afbe30b2e","content":"<p>It identifies an aspect of the Chicano movement that the text implies was overemphasized by scholars due to their own political orientations.&nbsp;</p>"},{"id":"f12eba5b-3532-4323-b5d0-0a34b5ed1909","content":"<p>It describes a common approach to studying the Chicano movement that, according to the text, obscures the ideological diversity of the movement&rsquo;s participants.&nbsp;</p>"},{"id":"7326a6ad-0805-4f6f-ac8b-1e3ff6facb6e","content":"<p>It summarizes the conventional method for analyzing the Chicano movement, which the text suggests creates a misleading impression of the effectiveness of neighborhood institutions and projects.</p>"}],"keys":["f12eba5b-3532-4323-b5d0-0a34b5ed1909"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text begins by mentioning scholarly accounts of the Chicano movement, which the underlined portion describes as tending \"to focus on the most militant, outspoken figures in the movement,\" making the movement as a whole seem uniformly radical. The text then indicates that the work of geographer Juan Herrera shows that focusing less on such militant figures and instead paying more attention to manifestations of the Chicano movement in less widely known neighborhood institutions and projects would reveal that the movement&rsquo;s participants embraced a range of political orientations and approaches. Thus, the underlined portion describes a common approach to studying the Chicano movement that, according to the text, obscures the ideological diversity of the movement&rsquo;s participants.</p><p>Choice A is incorrect. Though the underlined portion does present a trend in scholarship on the Chicano movement, the text does not indicate that other scholars have reevaluated their methods in light of Herrera&rsquo;s work. It only indicates that Herrera&rsquo;s work suggests that the work of those other scholars does not provide a complete picture of the Chicano movement. Choice B is incorrect. Though the underlined portion does identify an aspect of the Chicano movement that the text indicates has been overemphasized, the text does not discuss the political orientations of the scholars whose work is mentioned in the text. Choice D is incorrect. Though the underlined portion does summarize the conventional method for analyzing the Chicano movement, the rest of the text does not address the effectiveness of \"comparatively low-profile neighborhood institutions and projects.\" Instead, the text suggests that those projects were led by people with a variety of approaches to community activism.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323036,"updateDate":1730147323036}$SATQ$::jsonb, 1730147323036, 1730147323036),
    ($SATQ$1fa751f1$SATQ$, $SATQ$e4ff61a3-8e09-4f98-a23c-21f739f73535$SATQ$::uuid, $SATQ$9f1293f4-413e-4d82-9b3f-308d85d7933f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Handedness, a preferential use of either the right or left hand, typically is easy to observe in humans. Because this trait is present but less <span aria-hidden="true">______</span><span class="sr-only">blank</span> in many other animals, animal-behavior researchers often employ tasks specially designed to reveal individual animals&rsquo; preferences for a certain hand or paw.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"268b4a5f-d91f-48c1-9660-145c55ff6e37","content":"<p>recognizable</p>"},{"id":"fad0d9aa-8c9c-4522-a3e7-5aa582f20ad8","content":"<p>intriguing</p>"},{"id":"7b53961c-79f8-49b9-8030-b3fa50ecd16e","content":"<p>significant</p>"},{"id":"9d14a29c-f168-4a03-8600-88d13cef574c","content":"<p>useful</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["268b4a5f-d91f-48c1-9660-145c55ff6e37"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion about handedness in animals. As used in this context, &ldquo;recognizable&rdquo; means apparent or identifiable. The text indicates that handedness is &ldquo;easy to observe in humans,&rdquo; but that animal-behavior researchers use special tasks to determine handedness in other animals. This context and the use of &ldquo;less&rdquo; before the blank indicate that compared with handedness in humans, handedness in other animals is less recognizable. </p><p>Choice B is incorrect because there&rsquo;s nothing in the text to suggest that handedness is less &ldquo;intriguing,&rdquo; or fascinating, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn&rsquo;t suggest that handedness is more fascinating in humans. &nbsp;Choice C is incorrect because there&rsquo;s nothing in the text to suggest that handedness is less &ldquo;significant,&rdquo; or important or meaningful, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn&rsquo;t suggest that handedness is more significant in humans. Choice D is incorrect because &ldquo;useful,&rdquo; or functional or helpful, wouldn&rsquo;t make sense in context. The text focuses on the ease with which researchers can determine whether an animal or person is right- or left-handed, not on how useful handedness in nonhuman animals is compared with handedness in humans.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-948-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$65ce98d5-60be-45bf-b54e-e1dbf01974c1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1fa751f1","external_id":"e4ff61a3-8e09-4f98-a23c-21f739f73535","vaultid":"9f1293f4-413e-4d82-9b3f-308d85d7933f","uId":"b0016519-6c24-40d7-8ba1-e8d9dcd6f5af","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Handedness, a preferential use of either the right or left hand, typically is easy to observe in humans. Because this trait is present but less <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in many other animals, animal-behavior researchers often employ tasks specially designed to reveal individual animals&rsquo; preferences for a certain hand or paw.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"268b4a5f-d91f-48c1-9660-145c55ff6e37","content":"<p>recognizable</p>"},{"id":"fad0d9aa-8c9c-4522-a3e7-5aa582f20ad8","content":"<p>intriguing</p>"},{"id":"7b53961c-79f8-49b9-8030-b3fa50ecd16e","content":"<p>significant</p>"},{"id":"9d14a29c-f168-4a03-8600-88d13cef574c","content":"<p>useful</p>"}],"keys":["268b4a5f-d91f-48c1-9660-145c55ff6e37"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion about handedness in animals. As used in this context, &ldquo;recognizable&rdquo; means apparent or identifiable. The text indicates that handedness is &ldquo;easy to observe in humans,&rdquo; but that animal-behavior researchers use special tasks to determine handedness in other animals. This context and the use of &ldquo;less&rdquo; before the blank indicate that compared with handedness in humans, handedness in other animals is less recognizable. </p><p>Choice B is incorrect because there&rsquo;s nothing in the text to suggest that handedness is less &ldquo;intriguing,&rdquo; or fascinating, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn&rsquo;t suggest that handedness is more fascinating in humans. &nbsp;Choice C is incorrect because there&rsquo;s nothing in the text to suggest that handedness is less &ldquo;significant,&rdquo; or important or meaningful, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn&rsquo;t suggest that handedness is more significant in humans. Choice D is incorrect because &ldquo;useful,&rdquo; or functional or helpful, wouldn&rsquo;t make sense in context. The text focuses on the ease with which researchers can determine whether an animal or person is right- or left-handed, not on how useful handedness in nonhuman animals is compared with handedness in humans.&nbsp;</p>","parenttemplatename":"OSP-948-WIC","parenttemplateid":"","templateclusterid":"65ce98d5-60be-45bf-b54e-e1dbf01974c1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$1fbf276a$SATQ$, $SATQ$a27aa59e-675f-4455-b846-dd16613ab152$SATQ$::uuid, $SATQ$05d245d7-c137-4480-9d94-7065a302dca9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Interruptions in the supply chain for microchips used in personal electronics have challenged an economist&rsquo;s assertion that retailers can expect robust growth in sales of those devices in the coming months. The delays are unlikely to <span aria-hidden="true">______</span><span class="sr-only">blank</span> her projection entirely but will almost certainly extend its time frame.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"dd225dbb-2b8d-4177-a63b-178ecd45c71f","content":"<p>dispute</p>"},{"id":"56b3fa86-e395-4649-8de3-ab599753d92a","content":"<p>withdraw</p>"},{"id":"2725feb5-54fb-40ae-8c76-68dcc006e3e7","content":"<p>underscore</p>"},{"id":"4cf863d6-a9c5-46b3-a78a-fb0ce7cdafa5","content":"<p>invalidate</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["4cf863d6-a9c5-46b3-a78a-fb0ce7cdafa5"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the economist&rsquo;s claim about sales of personal electronic devices. In this context, &ldquo;invalidate&rdquo; most nearly means nullify or make invalid. The text indicates that interruptions in the supply of microchips for personal electronics &ldquo;have challenged&rdquo; the economist&rsquo;s claim that sales of personal electronics will show strong growth in the coming months. The text goes on to clarify the effect of the delays on the economist&rsquo;s projection, stating that the delays are very likely to extend the time frame over which the projected growth in sales will occur. This context suggests that the delays are unlikely to invalidate the economist&rsquo;s projection entirely&mdash;the delays will probably alter the time frame of the projection, not nullify it or make it invalid. </p><p>Choice A is incorrect because saying that the delays are unlikely to &ldquo;dispute,&rdquo; or argue against, the economist&rsquo;s projection wouldn&rsquo;t make sense. Since the delays are an inanimate circumstance, they couldn&rsquo;t argue against a prediction about the sales of personal electronics. Choice B is incorrect because saying that the delays are unlikely to &ldquo;withdraw,&rdquo; or remove from consideration, the economist&rsquo;s projection wouldn&rsquo;t make sense. Although the economist could withdraw her projection because of the delays, the delays themselves couldn&rsquo;t withdraw her projection since they&rsquo;re an inanimate circumstance and thus can&rsquo;t choose to remove something from consideration. Choice C is incorrect because there&rsquo;s nothing in the text to suggest that the delays will &ldquo;underscore,&rdquo; or emphasize, the economist&rsquo;s projection. Instead, the text suggests that the delays are likely to extend the time frame of the economist&rsquo;s projection but not to undermine the projection entirely.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-968-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$3e4a97d0-d32f-4c17-93f0-ca2b51262133$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1fbf276a","external_id":"a27aa59e-675f-4455-b846-dd16613ab152","vaultid":"05d245d7-c137-4480-9d94-7065a302dca9","uId":"cb6f525b-56bd-4fc2-9048-7524299db3be","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Interruptions in the supply chain for microchips used in personal electronics have challenged an economist&rsquo;s assertion that retailers can expect robust growth in sales of those devices in the coming months. The delays are unlikely to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> her projection entirely but will almost certainly extend its time frame.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"dd225dbb-2b8d-4177-a63b-178ecd45c71f","content":"<p>dispute</p>"},{"id":"56b3fa86-e395-4649-8de3-ab599753d92a","content":"<p>withdraw</p>"},{"id":"2725feb5-54fb-40ae-8c76-68dcc006e3e7","content":"<p>underscore</p>"},{"id":"4cf863d6-a9c5-46b3-a78a-fb0ce7cdafa5","content":"<p>invalidate</p>"}],"keys":["4cf863d6-a9c5-46b3-a78a-fb0ce7cdafa5"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the economist&rsquo;s claim about sales of personal electronic devices. In this context, &ldquo;invalidate&rdquo; most nearly means nullify or make invalid. The text indicates that interruptions in the supply of microchips for personal electronics &ldquo;have challenged&rdquo; the economist&rsquo;s claim that sales of personal electronics will show strong growth in the coming months. The text goes on to clarify the effect of the delays on the economist&rsquo;s projection, stating that the delays are very likely to extend the time frame over which the projected growth in sales will occur. This context suggests that the delays are unlikely to invalidate the economist&rsquo;s projection entirely&mdash;the delays will probably alter the time frame of the projection, not nullify it or make it invalid. </p><p>Choice A is incorrect because saying that the delays are unlikely to &ldquo;dispute,&rdquo; or argue against, the economist&rsquo;s projection wouldn&rsquo;t make sense. Since the delays are an inanimate circumstance, they couldn&rsquo;t argue against a prediction about the sales of personal electronics. Choice B is incorrect because saying that the delays are unlikely to &ldquo;withdraw,&rdquo; or remove from consideration, the economist&rsquo;s projection wouldn&rsquo;t make sense. Although the economist could withdraw her projection because of the delays, the delays themselves couldn&rsquo;t withdraw her projection since they&rsquo;re an inanimate circumstance and thus can&rsquo;t choose to remove something from consideration. Choice C is incorrect because there&rsquo;s nothing in the text to suggest that the delays will &ldquo;underscore,&rdquo; or emphasize, the economist&rsquo;s projection. Instead, the text suggests that the delays are likely to extend the time frame of the economist&rsquo;s projection but not to undermine the projection entirely.&nbsp;</p>","parenttemplatename":"OSP-968-WIC","parenttemplateid":"","templateclusterid":"3e4a97d0-d32f-4c17-93f0-ca2b51262133","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$213248f7$SATQ$, $SATQ$adaad827-47ac-4562-bba0-852ef6d03236$SATQ$::uuid, $SATQ$870d3f5a-c52f-4a64-a0b4-a2a7eaffd852$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Lewis Carroll&rsquo;s 1865 novel <em>Alice&rsquo;s Adventures in Wonderland</em>.</p>
<blockquote>
<p>&ldquo;The second thing is to find my way into that lovely garden. I think that will be the best plan.&rdquo; It sounded like an excellent plan, no doubt, and very neatly and <span role="region" aria-label="Referenced Content"><u>simply</u></span> arranged; the only difficulty was, that Alice had not the smallest idea how to set about it.</p>
</blockquote>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;simply&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"78ce1266-0b7f-403f-b2c6-512e880a5f00","content":"<p>Faintly</p>"},{"id":"7bcc3b57-a1c9-430e-be91-d8a2ce2ff1c5","content":"<p>Hastily</p>"},{"id":"c088144b-8cc8-494f-a401-ca642b74914c","content":"<p>Easily</p>"},{"id":"e221329a-eeb4-448d-8d3b-5319c23be575","content":"<p>Foolishly</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c088144b-8cc8-494f-a401-ca642b74914c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because as used in the text, &ldquo;simply&rdquo; most nearly means easily, or involving minimal difficulty or effort. The text first provides Alice&rsquo;s reflections on her plan to gain access to a garden and then offers commentary on her plan by the novel&rsquo;s narrator. The text indicates that a reason Alice likes her plan despite not being fully thought through is that she nonetheless believes it can be efficiently arranged. In other words, the text indicates that one of the supposed benefits of Alice&rsquo;s plan is that it can be easily arranged. </p><p>Choice A is incorrect because the text describes how Alice&rsquo;s plan can be arranged, and it wouldn&rsquo;t make sense to say that it can be arranged &ldquo;faintly,&rdquo; or with little strength or not strongly. Instead, the text indicates that the plan can be arranged with little difficulty.&nbsp;Choice B is incorrect. Although in some contexts &ldquo;simply&rdquo; can mean quickly, hastily, or hurriedly, the word &ldquo;hastily&rdquo; indicates that something is done too quickly. Although it may be true that Alice&rsquo;s plan was made in haste, the text doesn&rsquo;t focus on this aspect of her plan. Instead, the text focuses on the plan&rsquo;s seemingly good qualities, saying that Alice thinks of it as &ldquo;the best,&rdquo; and the narrator refers to it as &ldquo;excellent&rdquo; and &ldquo;neatly,&rdquo; or efficiently, arranged. Choice D is incorrect. Although in some contexts &ldquo;simply&rdquo; can mean foolishly, or lacking good sense, it doesn&rsquo;t have this meaning in this context. Although the text says that Alice doesn&rsquo;t know how to go about her plan, it begins by presenting her plan in a positive light: Alice describes her plan as &ldquo;the best,&rdquo; and the narrator refers to the plan as &ldquo;excellent&rdquo; and &ldquo;neatly,&rdquo; or efficiently, arranged. </p>$SATQ$, false, 0, $SATQ$OSP-034-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$be5b3add-983c-4de7-84ed-d853eefa9025$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"213248f7","external_id":"adaad827-47ac-4562-bba0-852ef6d03236","vaultid":"870d3f5a-c52f-4a64-a0b4-a2a7eaffd852","uId":"e8c4705b-3a03-49b6-ad14-9f78a98e4288","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The following text is adapted from Lewis Carroll&rsquo;s 1865 novel <em>Alice&rsquo;s Adventures in Wonderland</em>.</p>\n<blockquote>\n<p>&ldquo;The second thing is to find my way into that lovely garden. I think that will be the best plan.&rdquo; It sounded like an excellent plan, no doubt, and very neatly and <span role=\"region\" aria-label=\"Referenced Content\"><u>simply</u></span> arranged; the only difficulty was, that Alice had not the smallest idea how to set about it.</p>\n</blockquote>","stem":"<p>As used in the text, what does the word &ldquo;simply&rdquo; most nearly mean?</p>","answerOptions":[{"id":"78ce1266-0b7f-403f-b2c6-512e880a5f00","content":"<p>Faintly</p>"},{"id":"7bcc3b57-a1c9-430e-be91-d8a2ce2ff1c5","content":"<p>Hastily</p>"},{"id":"c088144b-8cc8-494f-a401-ca642b74914c","content":"<p>Easily</p>"},{"id":"e221329a-eeb4-448d-8d3b-5319c23be575","content":"<p>Foolishly</p>"}],"keys":["c088144b-8cc8-494f-a401-ca642b74914c"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because as used in the text, &ldquo;simply&rdquo; most nearly means easily, or involving minimal difficulty or effort. The text first provides Alice&rsquo;s reflections on her plan to gain access to a garden and then offers commentary on her plan by the novel&rsquo;s narrator. The text indicates that a reason Alice likes her plan despite not being fully thought through is that she nonetheless believes it can be efficiently arranged. In other words, the text indicates that one of the supposed benefits of Alice&rsquo;s plan is that it can be easily arranged. </p><p>Choice A is incorrect because the text describes how Alice&rsquo;s plan can be arranged, and it wouldn&rsquo;t make sense to say that it can be arranged &ldquo;faintly,&rdquo; or with little strength or not strongly. Instead, the text indicates that the plan can be arranged with little difficulty.&nbsp;Choice B is incorrect. Although in some contexts &ldquo;simply&rdquo; can mean quickly, hastily, or hurriedly, the word &ldquo;hastily&rdquo; indicates that something is done too quickly. Although it may be true that Alice&rsquo;s plan was made in haste, the text doesn&rsquo;t focus on this aspect of her plan. Instead, the text focuses on the plan&rsquo;s seemingly good qualities, saying that Alice thinks of it as &ldquo;the best,&rdquo; and the narrator refers to it as &ldquo;excellent&rdquo; and &ldquo;neatly,&rdquo; or efficiently, arranged. Choice D is incorrect. Although in some contexts &ldquo;simply&rdquo; can mean foolishly, or lacking good sense, it doesn&rsquo;t have this meaning in this context. Although the text says that Alice doesn&rsquo;t know how to go about her plan, it begins by presenting her plan in a positive light: Alice describes her plan as &ldquo;the best,&rdquo; and the narrator refers to the plan as &ldquo;excellent&rdquo; and &ldquo;neatly,&rdquo; or efficiently, arranged. </p>","parenttemplatename":"OSP-034-WIC","parenttemplateid":"","templateclusterid":"be5b3add-983c-4de7-84ed-d853eefa9025","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959320,"updateDate":1691007959320}$SATQ$::jsonb, 1691007959320, 1691007959320),
    ($SATQ$213a25d1$SATQ$, $SATQ$e662866f-b53a-4050-9564-07e4a17b9e5a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Paul Laurence Dunbar&rsquo;s 1913 poem &ldquo;The Poet and His Song.&rdquo;</p>
<blockquote class="dap_poemexcerpt">
<p>A song is but a little thing,</p>
<p>And yet what joy it is to sing!</p>
<p>In hours of toil it gives me zest,</p>
<p>And when at eve I long for rest;</p>
<p>When cows come home along the bars,</p>
<p style="padding-left: 1em;">And in the fold I hear the bell,</p>
<p>As Night, the shepherd, herds his stars,</p>
<p style="padding-left: 1em;">I sing my song, and all is well.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"068a2b89-263f-419b-bf38-5ecd78bbe4f1","content":"<p>To convey how engaging in song makes the speaker feel</p>"},{"id":"54dac90f-b27b-43c5-82d2-34bc50d144a7","content":"<p>To compare the speaker to a singing shepherd</p>"},{"id":"cd5f6d40-6f43-46c8-a8fc-fe14f990a5fd","content":"<p>To portray the speaker&rsquo;s excitement about farming</p>"},{"id":"0e3fb0d9-f380-4bb8-b19e-514f1849ff32","content":"<p>To describe the pieces of music the speaker enjoys hearing</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["068a2b89-263f-419b-bf38-5ecd78bbe4f1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because is accurately states the main purpose of the text. The text begins by declaring that although a song is "but a little thing," or seemingly insignificant, singing it brings joy and gives the speaker of the text "zest," or excitement, in "hours of toil." The remainder of the text explores the idea that as night is falling, singing allows the speaker to feel that "all is well." Thus, the main purpose of the text is to convey how engaging in song makes the speaker feel.</p><p>Choice B is incorrect. Although the text mentions a shepherd, it neither indicates that the shepherd is singing nor does it compare the shepherd to the speaker. Choice C is incorrect. The text indicates that the speaker works hard, engaging in "hours of toil," and it can be inferred that the speaker likely lives in a rural area, since cows and a cowbell can be heard nearby. However, the text does not suggest that the speaker is a farmer or feels excited about farming. Moreover, the shepherd in the text is not a literal reference to someone who herds sheep but instead a figurative description of the moon as the shepherd of the stars. Choice D is incorrect because in the text, the speaker is singing a song, not listening to others sing one. Moreover, the text describes the feelings that the speaker has when singing a song, not the song itself.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"213a25d1","external_id":"e662866f-b53a-4050-9564-07e4a17b9e5a","vaultid":null,"uId":"70d5421e-f9db-4ec5-8547-47a13fba6de4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is from Paul Laurence Dunbar&rsquo;s 1913 poem &ldquo;The Poet and His Song.&rdquo;</p>\n<blockquote class=\"dap_poemexcerpt\">\n<p>A song is but a little thing,</p>\n<p>And yet what joy it is to sing!</p>\n<p>In hours of toil it gives me zest,</p>\n<p>And when at eve I long for rest;</p>\n<p>When cows come home along the bars,</p>\n<p style=\"padding-left: 1em;\">And in the fold I hear the bell,</p>\n<p>As Night, the shepherd, herds his stars,</p>\n<p style=\"padding-left: 1em;\">I sing my song, and all is well.</p>\n</blockquote>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"068a2b89-263f-419b-bf38-5ecd78bbe4f1","content":"<p>To convey how engaging in song makes the speaker feel</p>"},{"id":"54dac90f-b27b-43c5-82d2-34bc50d144a7","content":"<p>To compare the speaker to a singing shepherd</p>"},{"id":"cd5f6d40-6f43-46c8-a8fc-fe14f990a5fd","content":"<p>To portray the speaker&rsquo;s excitement about farming</p>"},{"id":"0e3fb0d9-f380-4bb8-b19e-514f1849ff32","content":"<p>To describe the pieces of music the speaker enjoys hearing</p>"}],"keys":["068a2b89-263f-419b-bf38-5ecd78bbe4f1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because is accurately states the main purpose of the text. The text begins by declaring that although a song is \"but a little thing,\" or seemingly insignificant, singing it brings joy and gives the speaker of the text \"zest,\" or excitement, in \"hours of toil.\" The remainder of the text explores the idea that as night is falling, singing allows the speaker to feel that \"all is well.\" Thus, the main purpose of the text is to convey how engaging in song makes the speaker feel.</p><p>Choice B is incorrect. Although the text mentions a shepherd, it neither indicates that the shepherd is singing nor does it compare the shepherd to the speaker. Choice C is incorrect. The text indicates that the speaker works hard, engaging in \"hours of toil,\" and it can be inferred that the speaker likely lives in a rural area, since cows and a cowbell can be heard nearby. However, the text does not suggest that the speaker is a farmer or feels excited about farming. Moreover, the shepherd in the text is not a literal reference to someone who herds sheep but instead a figurative description of the moon as the shepherd of the stars. Choice D is incorrect because in the text, the speaker is singing a song, not listening to others sing one. Moreover, the text describes the feelings that the speaker has when singing a song, not the song itself.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$21d95d1d$SATQ$, $SATQ$e5b204ce-8d37-415b-a8b5-83f606ed8d83$SATQ$::uuid, $SATQ$c57b94d9-bdde-4303-8ea3-ec82e62e5929$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Ofelia Zepeda&rsquo;s contributions to the field of linguistics are <span aria-hidden="true">______</span><span class="sr-only">blank</span>: her many accomplishments include working as a linguistics professor and bilingual poet, authoring the first Tohono O&rsquo;odham grammar book, and co-founding the American Indian Language Development Institute. </p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"ff822004-f7af-4a81-9bb1-68167cca1fb5","content":"<p>pragmatic</p>"},{"id":"656ebd69-9a8c-4a05-86d5-1798dca8ab06","content":"<p>controversial</p>"},{"id":"b65e53da-53f8-49cf-bb89-c19b8040dbff","content":"<p>extensive</p>"},{"id":"fe36a51f-e5b8-49a9-8d93-d6d163636ef8","content":"<p>universal</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b65e53da-53f8-49cf-bb89-c19b8040dbff"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of how Ofelia Zepeda has contributed to the field of linguistics. As used in this context, &ldquo;extensive&rdquo; means having a wide or considerable extent. The text indicates that Zepeda&rsquo;s many accomplishments in linguistics are varied, including teaching linguistics, writing poetry in more than one language, creating a grammar book, and co-founding a language institute. This context supports the idea that Zepeda&rsquo;s contributions to the field are extensive. </p><p>Choice A is incorrect because the sentence presents Zepeda&rsquo;s accomplishments as examples to support the claim made in the first part of the sentence. It wouldn&rsquo;t make sense to say that achievements as a professor, poet and author, and co-founder of a language institute demonstrate that Zepeda&rsquo;s contributions in her field are &ldquo;pragmatic,&rdquo; or related to practical matters and not involving intellectual or artistic matters. Choice B is incorrect because the sentence presents Zepeda&rsquo;s accomplishments as a professor, poet and author, and co-founder of a language institute as examples to support the claim made in the first part of the sentence. There&rsquo;s no reason to believe that the positive achievements listed demonstrate that Zepeda&rsquo;s contributions in her field are &ldquo;controversial,&rdquo; or have caused disputes and opposing viewpoints. Choice D is incorrect because in this context, &ldquo;universal&rdquo; would mean including or covering everything in a group. The sentence presents Zepeda&rsquo;s accomplishments as examples to support the claim made in the first part of the sentence, and it wouldn&rsquo;t make sense to say that these specific achievements&mdash;particularly as the author of a grammar book specific to the Tohono O&rsquo;odham language&mdash;demonstrate that Zepeda&rsquo;s contributions relate to everything in the field of linguistics. </p>$SATQ$, false, 0, $SATQ$OSP-919-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$35084198-8ce3-40af-9595-a7702baf20ed$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"21d95d1d","external_id":"e5b204ce-8d37-415b-a8b5-83f606ed8d83","vaultid":"c57b94d9-bdde-4303-8ea3-ec82e62e5929","uId":"c863e5be-fdc6-4b06-8622-f106226d428b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Ofelia Zepeda&rsquo;s contributions to the field of linguistics are <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>: her many accomplishments include working as a linguistics professor and bilingual poet, authoring the first Tohono O&rsquo;odham grammar book, and co-founding the American Indian Language Development Institute. </p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"ff822004-f7af-4a81-9bb1-68167cca1fb5","content":"<p>pragmatic</p>"},{"id":"656ebd69-9a8c-4a05-86d5-1798dca8ab06","content":"<p>controversial</p>"},{"id":"b65e53da-53f8-49cf-bb89-c19b8040dbff","content":"<p>extensive</p>"},{"id":"fe36a51f-e5b8-49a9-8d93-d6d163636ef8","content":"<p>universal</p>"}],"keys":["b65e53da-53f8-49cf-bb89-c19b8040dbff"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of how Ofelia Zepeda has contributed to the field of linguistics. As used in this context, &ldquo;extensive&rdquo; means having a wide or considerable extent. The text indicates that Zepeda&rsquo;s many accomplishments in linguistics are varied, including teaching linguistics, writing poetry in more than one language, creating a grammar book, and co-founding a language institute. This context supports the idea that Zepeda&rsquo;s contributions to the field are extensive. </p><p>Choice A is incorrect because the sentence presents Zepeda&rsquo;s accomplishments as examples to support the claim made in the first part of the sentence. It wouldn&rsquo;t make sense to say that achievements as a professor, poet and author, and co-founder of a language institute demonstrate that Zepeda&rsquo;s contributions in her field are &ldquo;pragmatic,&rdquo; or related to practical matters and not involving intellectual or artistic matters. Choice B is incorrect because the sentence presents Zepeda&rsquo;s accomplishments as a professor, poet and author, and co-founder of a language institute as examples to support the claim made in the first part of the sentence. There&rsquo;s no reason to believe that the positive achievements listed demonstrate that Zepeda&rsquo;s contributions in her field are &ldquo;controversial,&rdquo; or have caused disputes and opposing viewpoints. Choice D is incorrect because in this context, &ldquo;universal&rdquo; would mean including or covering everything in a group. The sentence presents Zepeda&rsquo;s accomplishments as examples to support the claim made in the first part of the sentence, and it wouldn&rsquo;t make sense to say that these specific achievements&mdash;particularly as the author of a grammar book specific to the Tohono O&rsquo;odham language&mdash;demonstrate that Zepeda&rsquo;s contributions relate to everything in the field of linguistics. </p>","parenttemplatename":"OSP-919-WIC","parenttemplateid":"","templateclusterid":"35084198-8ce3-40af-9595-a7702baf20ed","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959355,"updateDate":1691007959355}$SATQ$::jsonb, 1691007959355, 1691007959355),
    ($SATQ$22105871$SATQ$, $SATQ$4c36e647-a8e3-4ed1-a813-04d6818058b1$SATQ$::uuid, $SATQ$3a8d533c-aca8-45f0-9742-b95c3a3a9a0b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><strong>Text 1</strong></p>
<p>In a study of insect behavior, Samadi Galpayage and colleagues presented bumblebees with small wooden balls and observed many of the bees clinging to, rolling, and dragging the objects. The researchers provided no external rewards (such as food) to encourage these interactions. <u>The bees simply appeared to be playing&mdash;and for no other reason than because they were having fun</u>.</p>
<p><strong>Text 2</strong></p>
<p>Insects do not have cortexes or other brain areas associated with emotions in humans. Still, Galpayage and her team have shown that bumblebees may engage in play, possibly experiencing some kind of positive emotional state. Other studies have suggested that bees experience negative emotional states (for example, stress), but as Galpayage and her team have acknowledged, emotions in insects, if they do indeed exist, are likely very rudimentary.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the author of Text 2 most likely respond to the underlined portion of Text 1?</p>$SATQ$, $SATQ$[{"id":"8a96dd71-89cf-4f09-bbbd-c05f125f369f","content":"<p>By objecting that the bees were actually experiencing a negative feeling akin to stress rather than a positive feeling</p>"},{"id":"4ab21c75-563e-4cb0-92b1-f753a5c1ef6a","content":"<p>By arguing that some insects other than bumblebees may be capable of experiencing complex emotional states</p>"},{"id":"6d4a12a7-2e28-4ec1-a5fc-f1624d8bd5ab","content":"<p>By pointing out that even humans sometimes struggle to have fun while engaging in play</p>"},{"id":"9a884ba7-de57-425d-8ce0-6fb22b98e517","content":"<p>By noting that if the bees were truly playing, any positive feelings they may have experienced were probably quite basic</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["9a884ba7-de57-425d-8ce0-6fb22b98e517"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The author of Text 2 agrees with the author of Text 1 that bumblebees may engage in play and possibly experience some kind of positive emotional state. However, the author of Text 2 also qualifies this claim by stating that emotions in insects, if they do exist, are &ldquo;likely very rudimentary.&rdquo; </p><p>Choice A is incorrect. While Text 2 states that other studies might indicate &ldquo;negative emotional states&rdquo; in bees, it does not contradict the findings from the Galpayage study&mdash;that the bees might have been having fun. Choice B is incorrect. The author of Text 2 does not mention or imply that any insects, including bumblebees, are capable of experiencing complex emotional states. The author of Text 2 states that if insects do feel emotions, those emotions are &ldquo;likely very rudimentary.&rdquo; Choice C is incorrect. The author of Text 2 does not compare or contrast the behavior or emotions of insects and humans, and neither does the author of Text 1. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M010$SATQ$, $SATQ$$SATQ$, $SATQ$3fba8883-822d-4252-a55a-0bb8a041ba7e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"22105871","external_id":"4c36e647-a8e3-4ed1-a813-04d6818058b1","vaultid":"3a8d533c-aca8-45f0-9742-b95c3a3a9a0b","uId":"cfd21ff8-0059-4d90-8add-b08b605c5d6b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><strong>Text 1</strong></p>\n<p>In a study of insect behavior, Samadi Galpayage and colleagues presented bumblebees with small wooden balls and observed many of the bees clinging to, rolling, and dragging the objects. The researchers provided no external rewards (such as food) to encourage these interactions. <u>The bees simply appeared to be playing&mdash;and for no other reason than because they were having fun</u>.</p>\n<p><strong>Text 2</strong></p>\n<p>Insects do not have cortexes or other brain areas associated with emotions in humans. Still, Galpayage and her team have shown that bumblebees may engage in play, possibly experiencing some kind of positive emotional state. Other studies have suggested that bees experience negative emotional states (for example, stress), but as Galpayage and her team have acknowledged, emotions in insects, if they do indeed exist, are likely very rudimentary.</p>","stem":"<p>Based on the texts, how would the author of Text 2 most likely respond to the underlined portion of Text 1?</p>","answerOptions":[{"id":"8a96dd71-89cf-4f09-bbbd-c05f125f369f","content":"<p>By objecting that the bees were actually experiencing a negative feeling akin to stress rather than a positive feeling</p>"},{"id":"4ab21c75-563e-4cb0-92b1-f753a5c1ef6a","content":"<p>By arguing that some insects other than bumblebees may be capable of experiencing complex emotional states</p>"},{"id":"6d4a12a7-2e28-4ec1-a5fc-f1624d8bd5ab","content":"<p>By pointing out that even humans sometimes struggle to have fun while engaging in play</p>"},{"id":"9a884ba7-de57-425d-8ce0-6fb22b98e517","content":"<p>By noting that if the bees were truly playing, any positive feelings they may have experienced were probably quite basic</p>"}],"keys":["9a884ba7-de57-425d-8ce0-6fb22b98e517"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The author of Text 2 agrees with the author of Text 1 that bumblebees may engage in play and possibly experience some kind of positive emotional state. However, the author of Text 2 also qualifies this claim by stating that emotions in insects, if they do exist, are &ldquo;likely very rudimentary.&rdquo; </p><p>Choice A is incorrect. While Text 2 states that other studies might indicate &ldquo;negative emotional states&rdquo; in bees, it does not contradict the findings from the Galpayage study&mdash;that the bees might have been having fun. Choice B is incorrect. The author of Text 2 does not mention or imply that any insects, including bumblebees, are capable of experiencing complex emotional states. The author of Text 2 states that if insects do feel emotions, those emotions are &ldquo;likely very rudimentary.&rdquo; Choice C is incorrect. The author of Text 2 does not compare or contrast the behavior or emotions of insects and humans, and neither does the author of Text 1. </p>","parenttemplatename":"OSP-KA-CTC-M010","parenttemplateid":"","templateclusterid":"3fba8883-822d-4252-a55a-0bb8a041ba7e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$22a41819$SATQ$, $SATQ$ca10cb5e-4485-43c8-ad27-a479f82d04a8$SATQ$::uuid, $SATQ$515b2aba-481b-4745-9fca-023191178760$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Rejecting the premise that the literary magazine <em>Ebony and Topaz</em> (1927) should present a unified vision of Black American identity, editor Charles S. Johnson fostered his contributors&rsquo; diverse perspectives by promoting their authorial autonomy. Johnson&rsquo;s self-effacement diverged from the editorial stances of W.E.B. Du Bois and Alain Locke, whose decisions for their publications were more <span aria-hidden="true">______</span><span class="sr-only">blank</span>.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"ec8e6f0a-edc8-465c-9975-125c3b6629f1","content":"<p>proficient</p>"},{"id":"e4a9424c-4a0e-4fa3-b5d3-61383d53698e","content":"<p>dogmatic</p>"},{"id":"b9ec8e32-8cf2-480a-9164-c207a8dec8e6","content":"<p>ambiguous</p>"},{"id":"d6434596-055b-4373-ae34-7af7272ee058","content":"<p>unpretentious</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e4a9424c-4a0e-4fa3-b5d3-61383d53698e"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. A person who is "dogmatic" believes strongly that their principles and opinions are true. Because Du Bois and Locke are implied to have one "unified vision" of Black American identity that they prioritize over the "diverse perspectives" of different writers, they can be described as dogmatic.</p><p>Choice A is incorrect. "Proficient" means "skilled." Du Bois and Locke are contrasted with Johnson, but nothing in the text suggests that Johnson was not skilled at making editorial decisions. Based on the text, the three editors just have different styles; they&rsquo;re not necessarily more or less skilled. Choice C is incorrect. "Ambiguous" means "unclear" or "open to multiple interpretations." However, it&rsquo;s actually Johnson who encouraged multiple interpretations ("diverse perspectives"). Since Du Bois and Locke are said to "diverge" from Johnson, we can assume that the views they published were not ambiguous, but instead clear and firm (a "unified vision"). Choice D is incorrect. "Unpretentious" means "not trying to impress others with greater skill or importance than is actually possessed." Du Bois and Locke are contrasted with Johnson, but nothing in the text suggests that Johnson is pretentious (trying to impress others).</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-H006$SATQ$, $SATQ$$SATQ$, $SATQ$1fdb07a4-2a3b-4251-8091-2285a15aaf60$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"22a41819","external_id":"ca10cb5e-4485-43c8-ad27-a479f82d04a8","vaultid":"515b2aba-481b-4745-9fca-023191178760","uId":"014c8ced-f28a-4490-b253-a19485d3d259","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Rejecting the premise that the literary magazine <em>Ebony and Topaz</em> (1927) should present a unified vision of Black American identity, editor Charles S. Johnson fostered his contributors&rsquo; diverse perspectives by promoting their authorial autonomy. Johnson&rsquo;s self-effacement diverged from the editorial stances of W.E.B. Du Bois and Alain Locke, whose decisions for their publications were more <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"ec8e6f0a-edc8-465c-9975-125c3b6629f1","content":"<p>proficient</p>"},{"id":"e4a9424c-4a0e-4fa3-b5d3-61383d53698e","content":"<p>dogmatic</p>"},{"id":"b9ec8e32-8cf2-480a-9164-c207a8dec8e6","content":"<p>ambiguous</p>"},{"id":"d6434596-055b-4373-ae34-7af7272ee058","content":"<p>unpretentious</p>"}],"keys":["e4a9424c-4a0e-4fa3-b5d3-61383d53698e"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. A person who is \"dogmatic\" believes strongly that their principles and opinions are true. Because Du Bois and Locke are implied to have one \"unified vision\" of Black American identity that they prioritize over the \"diverse perspectives\" of different writers, they can be described as dogmatic.</p><p>Choice A is incorrect. \"Proficient\" means \"skilled.\" Du Bois and Locke are contrasted with Johnson, but nothing in the text suggests that Johnson was not skilled at making editorial decisions. Based on the text, the three editors just have different styles; they&rsquo;re not necessarily more or less skilled. Choice C is incorrect. \"Ambiguous\" means \"unclear\" or \"open to multiple interpretations.\" However, it&rsquo;s actually Johnson who encouraged multiple interpretations (\"diverse perspectives\"). Since Du Bois and Locke are said to \"diverge\" from Johnson, we can assume that the views they published were not ambiguous, but instead clear and firm (a \"unified vision\"). Choice D is incorrect. \"Unpretentious\" means \"not trying to impress others with greater skill or importance than is actually possessed.\" Du Bois and Locke are contrasted with Johnson, but nothing in the text suggests that Johnson is pretentious (trying to impress others).</p>","parenttemplatename":"OSP-KA-WIC-H006","parenttemplateid":"","templateclusterid":"1fdb07a4-2a3b-4251-8091-2285a15aaf60","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$236fee8e$SATQ$, $SATQ$271ff9dc-ee40-4cc3-b077-7d60cefb0e66$SATQ$::uuid, $SATQ$edb0fd74-14dd-463b-85d5-f2d34bacb9e4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Archeological excavation of Market Street Chinatown, a nineteenth-century Chinese American community in San Jose, California, provided the first evidence that Asian food products were imported to the United States in the 1800s: bones from a freshwater fish species native to Southeast Asia. <u><em>Jinshanzhuang</em>&mdash;Hong Kong&ndash;based import/export firms&mdash;likely coordinated the fish&rsquo;s transport from Chinese-operated fisheries in Vietnam and Malaysia to North American markets.</u> This route reveals the (often overlooked) multinational dimensions of the trade networks linking Chinese diaspora communities.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"5d6d73c8-7766-4b4c-995c-be33719e08b4","content":"<p>It explains why efforts to determine the country of origin of the items mentioned in the previous sentence remain inconclusive.</p>"},{"id":"718384c0-ff0c-447e-9bf3-fd3529258c94","content":"<p>It provides information that helps support a claim about a discovery&rsquo;s significance that is presented in the following sentence.</p>"},{"id":"aed00198-e7c8-45c2-8be6-cf4cf459a540","content":"<p>It traces the steps that were taken to locate and recover the objects that are described in the previous sentence.</p>"},{"id":"2baad181-78d7-4a42-8ff5-2d3921a8b8c3","content":"<p>It outlines a hypothesis that additional evidence discussed in the following sentence casts some doubt on.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["718384c0-ff0c-447e-9bf3-fd3529258c94"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The underlined sentence provides information about import/export firms, showing how Chinese communities across the world were connected by trade routes.</p><p>Choice A is incorrect. The underlined sentence never suggests that the countries of origin of the fish are in question&mdash;in fact, it tells us exactly where they came from. Choice C is incorrect. The passage never describes the steps taken to discover the fish bones described in the previous sentence. Choice D is incorrect. The underlined sentence doesn&rsquo;t outline a hypothesis but instead provides evidence. And the following sentence agrees with the underlined sentence, so we could eliminate this choice just for saying that the following sentence "casts some doubt on" the underlined one&mdash;partly wrong is all wrong.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-M008$SATQ$, $SATQ$$SATQ$, $SATQ$9bbf8b28-7650-4088-91b5-10cdab89f7f9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"236fee8e","external_id":"271ff9dc-ee40-4cc3-b077-7d60cefb0e66","vaultid":"edb0fd74-14dd-463b-85d5-f2d34bacb9e4","uId":"0d2a7aa4-0630-4de6-b251-a0dce3c73714","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Archeological excavation of Market Street Chinatown, a nineteenth-century Chinese American community in San Jose, California, provided the first evidence that Asian food products were imported to the United States in the 1800s: bones from a freshwater fish species native to Southeast Asia. <u><em>Jinshanzhuang</em>&mdash;Hong Kong&ndash;based import/export firms&mdash;likely coordinated the fish&rsquo;s transport from Chinese-operated fisheries in Vietnam and Malaysia to North American markets.</u> This route reveals the (often overlooked) multinational dimensions of the trade networks linking Chinese diaspora communities.</p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"5d6d73c8-7766-4b4c-995c-be33719e08b4","content":"<p>It explains why efforts to determine the country of origin of the items mentioned in the previous sentence remain inconclusive.</p>"},{"id":"718384c0-ff0c-447e-9bf3-fd3529258c94","content":"<p>It provides information that helps support a claim about a discovery&rsquo;s significance that is presented in the following sentence.</p>"},{"id":"aed00198-e7c8-45c2-8be6-cf4cf459a540","content":"<p>It traces the steps that were taken to locate and recover the objects that are described in the previous sentence.</p>"},{"id":"2baad181-78d7-4a42-8ff5-2d3921a8b8c3","content":"<p>It outlines a hypothesis that additional evidence discussed in the following sentence casts some doubt on.</p>"}],"keys":["718384c0-ff0c-447e-9bf3-fd3529258c94"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The underlined sentence provides information about import/export firms, showing how Chinese communities across the world were connected by trade routes.</p><p>Choice A is incorrect. The underlined sentence never suggests that the countries of origin of the fish are in question&mdash;in fact, it tells us exactly where they came from. Choice C is incorrect. The passage never describes the steps taken to discover the fish bones described in the previous sentence. Choice D is incorrect. The underlined sentence doesn&rsquo;t outline a hypothesis but instead provides evidence. And the following sentence agrees with the underlined sentence, so we could eliminate this choice just for saying that the following sentence \"casts some doubt on\" the underlined one&mdash;partly wrong is all wrong.</p>","parenttemplatename":"OSP-KA-TSP-M008","parenttemplateid":"","templateclusterid":"9bbf8b28-7650-4088-91b5-10cdab89f7f9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$2390e956$SATQ$, $SATQ$977ef86f-4402-4b16-9465-aecee8d7a18b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Ronyoung Kim creatively captures the Korean American immigrant experience in her novel <em>Clay Walls</em> by writing about a family from three <span aria-hidden="true">______</span><span class="sr-only">blank</span> perspectives. The first section of the novel is from the mother Haesu&rsquo;s perspective, the second is from the father Chun&rsquo;s perspective, and the last is from the daughter Faye&rsquo;s perspective.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word?</p>$SATQ$, $SATQ$[{"id":"c062e2ab-d818-4ab6-a286-c8d7822b0913","content":"<p>distinct</p>"},{"id":"47e0e228-84e8-4dad-b47e-dbda0ef39870","content":"<p>required</p>"},{"id":"c26b340f-eb9a-4fe3-ada2-9d429deee5fb","content":"<p>unintended</p>"},{"id":"6b586116-73d5-4db1-9f4a-dca454000f64","content":"<p>unknown</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c062e2ab-d818-4ab6-a286-c8d7822b0913"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Ronyoung Kim&rsquo;s novel <em>Clay Walls</em>. In this context, "distinct" means clearly separate and different. The text indicates that the novel consists of three sections and that each section is narrated from the perspective of a different character. This context supports the idea that Kim&rsquo;s novel features three distinct perspectives.</p><p>Choice B is incorrect because describing the three perspectives in Kim&rsquo;s novel as "required," or demanded as necessary to be done or provided, wouldn&rsquo;t make sense in context. When writing a novel, a novelist is free to choose to narrate the story from any number of perspectives. There&rsquo;s nothing in the text to indicate that providing three perspectives was demanded of Kim. Instead, the text focuses on identifying the three different perspectives featured in Kim&rsquo;s novel. Choice C is incorrect because describing the three perspectives in Kim&rsquo;s novel as "unintended," or not planned as a purpose or goal, wouldn&rsquo;t make sense in context. Authors make deliberate choices about the perspectives they feature in their works, and the text indicates that Kim chose to incorporate three different perspectives in her novel. Choice D is incorrect because describing the three perspectives in Kim&rsquo;s novel as "unknown," or not revealed, wouldn&rsquo;t make sense in context. The text directly identifies the three perspectives that appear in her novel as those of Faye and her two parents, Haesu and Chun, which indicates that the novel&rsquo;s perspectives are in fact known.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2390e956","external_id":"977ef86f-4402-4b16-9465-aecee8d7a18b","vaultid":null,"uId":"fe54422a-c60e-45fe-add4-0268dfae097d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Ronyoung Kim creatively captures the Korean American immigrant experience in her novel <em>Clay Walls</em> by writing about a family from three <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> perspectives. The first section of the novel is from the mother Haesu&rsquo;s perspective, the second is from the father Chun&rsquo;s perspective, and the last is from the daughter Faye&rsquo;s perspective.</p>","stem":"<p>Which choice completes the text with the most logical and precise word?</p>","answerOptions":[{"id":"c062e2ab-d818-4ab6-a286-c8d7822b0913","content":"<p>distinct</p>"},{"id":"47e0e228-84e8-4dad-b47e-dbda0ef39870","content":"<p>required</p>"},{"id":"c26b340f-eb9a-4fe3-ada2-9d429deee5fb","content":"<p>unintended</p>"},{"id":"6b586116-73d5-4db1-9f4a-dca454000f64","content":"<p>unknown</p>"}],"keys":["c062e2ab-d818-4ab6-a286-c8d7822b0913"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Ronyoung Kim&rsquo;s novel <em>Clay Walls</em>. In this context, \"distinct\" means clearly separate and different. The text indicates that the novel consists of three sections and that each section is narrated from the perspective of a different character. This context supports the idea that Kim&rsquo;s novel features three distinct perspectives.</p><p>Choice B is incorrect because describing the three perspectives in Kim&rsquo;s novel as \"required,\" or demanded as necessary to be done or provided, wouldn&rsquo;t make sense in context. When writing a novel, a novelist is free to choose to narrate the story from any number of perspectives. There&rsquo;s nothing in the text to indicate that providing three perspectives was demanded of Kim. Instead, the text focuses on identifying the three different perspectives featured in Kim&rsquo;s novel. Choice C is incorrect because describing the three perspectives in Kim&rsquo;s novel as \"unintended,\" or not planned as a purpose or goal, wouldn&rsquo;t make sense in context. Authors make deliberate choices about the perspectives they feature in their works, and the text indicates that Kim chose to incorporate three different perspectives in her novel. Choice D is incorrect because describing the three perspectives in Kim&rsquo;s novel as \"unknown,\" or not revealed, wouldn&rsquo;t make sense in context. The text directly identifies the three perspectives that appear in her novel as those of Faye and her two parents, Haesu and Chun, which indicates that the novel&rsquo;s perspectives are in fact known.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040),
    ($SATQ$23974d6c$SATQ$, $SATQ$2aa88c7d-f601-464b-8ce5-3d9bdc05cab6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>There are many famous examples of election pollsters making inaccurate predictions in presidential elections. But neuroscientist and election pollster Sam Wang has said that these prediction failures should not lead campaigns to <span aria-hidden="true">______</span><span class="sr-only">blank</span> election polling entirely. Polling is about more than just predicting the winner; throughout campaigns, it helps strategists identify where their efforts are most likely to be effective.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"e832d5a2-cc02-4610-947f-484d7d40b5a6","content":"<p>distort</p>"},{"id":"2b824ea1-2040-4c7d-b8a4-e0da150d26b3","content":"<p>enact</p>"},{"id":"a760b6c8-82ad-4786-821f-045f0fdfd534","content":"<p>neglect</p>"},{"id":"a2c1aeaf-9849-4346-8ed7-731c2ddea2fe","content":"<p>supplement</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["a760b6c8-82ad-4786-821f-045f0fdfd534"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of election polling. In this context, to &ldquo;neglect&rdquo; would mean to disregard or pay insufficient attention to something. The text states that there have been many cases of election pollsters incorrectly predicting presidential elections and then says that neuroscientist and pollster Sam Wang notes that campaigns shouldn&rsquo;t react to these failures in a certain way. The text then adds that polls are valuable for informing strategists&rsquo; efforts throughout campaigns, not just for predicting the outcome. This context conveys that Wang&rsquo;s advice is not to neglect, or disregard, polling because even though it sometimes fails to predict the winner, it can help improve campaign strategies.</p><p>Choice A is incorrect. In this context, to &ldquo;distort&rdquo; would mean to give a false or misleading account. Though the text states that many election pollsters have failed in their predictions in presidential elections, it gives no indication that Wang would therefore argue that campaigns shouldn&rsquo;t react to such polling failures by giving inaccurate accounts of election polling. Instead, the text emphasizes that polls have value beyond predicting winners, suggesting that Wang&rsquo;s point is that campaigns shouldn&rsquo;t stop polling entirely. Choice B is incorrect because it wouldn&rsquo;t make sense to suggest that Wang encourages campaigns not to &ldquo;enact,&rdquo; or establish, election polling; the text indicates that election polling is something that already takes place and that has value for campaign strategies even if it sometimes leads to inaccurate predictions of winners, suggesting an argument in favor of continuing to use election polling. Choice D is incorrect. Although the text indicates that many election pollsters have failed in their predictions in presidential elections, there&rsquo;s no reason to think Wang would say that these failures should lead campaigns <em>not</em> to &ldquo;supplement,&rdquo; or add to, election polling; it would be reasonable to suggest that campaigns <em>would</em> want to consider more than just election polling information if that information may lead to inaccurate predictions. Moreover, the text&rsquo;s main point is that polls provide some utility even if their predictions may be inaccurate, which suggests that Wang&rsquo;s recommendations pertain to whether campaigns should or shouldn&rsquo;t use polling data, not whether polling data should or shouldn&rsquo;t be supplemented with other kinds of information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"23974d6c","external_id":"2aa88c7d-f601-464b-8ce5-3d9bdc05cab6","vaultid":null,"uId":"2bcf600d-8479-4bf1-900a-1a3c38c65c10","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>There are many famous examples of election pollsters making inaccurate predictions in presidential elections. But neuroscientist and election pollster Sam Wang has said that these prediction failures should not lead campaigns to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> election polling entirely. Polling is about more than just predicting the winner; throughout campaigns, it helps strategists identify where their efforts are most likely to be effective.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"e832d5a2-cc02-4610-947f-484d7d40b5a6","content":"<p>distort</p>"},{"id":"2b824ea1-2040-4c7d-b8a4-e0da150d26b3","content":"<p>enact</p>"},{"id":"a760b6c8-82ad-4786-821f-045f0fdfd534","content":"<p>neglect</p>"},{"id":"a2c1aeaf-9849-4346-8ed7-731c2ddea2fe","content":"<p>supplement</p>"}],"keys":["a760b6c8-82ad-4786-821f-045f0fdfd534"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of election polling. In this context, to &ldquo;neglect&rdquo; would mean to disregard or pay insufficient attention to something. The text states that there have been many cases of election pollsters incorrectly predicting presidential elections and then says that neuroscientist and pollster Sam Wang notes that campaigns shouldn&rsquo;t react to these failures in a certain way. The text then adds that polls are valuable for informing strategists&rsquo; efforts throughout campaigns, not just for predicting the outcome. This context conveys that Wang&rsquo;s advice is not to neglect, or disregard, polling because even though it sometimes fails to predict the winner, it can help improve campaign strategies.</p><p>Choice A is incorrect. In this context, to &ldquo;distort&rdquo; would mean to give a false or misleading account. Though the text states that many election pollsters have failed in their predictions in presidential elections, it gives no indication that Wang would therefore argue that campaigns shouldn&rsquo;t react to such polling failures by giving inaccurate accounts of election polling. Instead, the text emphasizes that polls have value beyond predicting winners, suggesting that Wang&rsquo;s point is that campaigns shouldn&rsquo;t stop polling entirely. Choice B is incorrect because it wouldn&rsquo;t make sense to suggest that Wang encourages campaigns not to &ldquo;enact,&rdquo; or establish, election polling; the text indicates that election polling is something that already takes place and that has value for campaign strategies even if it sometimes leads to inaccurate predictions of winners, suggesting an argument in favor of continuing to use election polling. Choice D is incorrect. Although the text indicates that many election pollsters have failed in their predictions in presidential elections, there&rsquo;s no reason to think Wang would say that these failures should lead campaigns <em>not</em> to &ldquo;supplement,&rdquo; or add to, election polling; it would be reasonable to suggest that campaigns <em>would</em> want to consider more than just election polling information if that information may lead to inaccurate predictions. Moreover, the text&rsquo;s main point is that polls provide some utility even if their predictions may be inaccurate, which suggests that Wang&rsquo;s recommendations pertain to whether campaigns should or shouldn&rsquo;t use polling data, not whether polling data should or shouldn&rsquo;t be supplemented with other kinds of information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$271a5017$SATQ$, $SATQ$9cd9bd44-1c9d-4da9-b40a-e9c317cdd49d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Akwaeke Emezi&rsquo;s 2019 novel <em>Pet</em>. Jam is a teenager who lives with her father, Aloe, and her mother, Bitter, who is a painter.</p>
<blockquote>
<p>Bitter finished the painting in the dark morning of a day&mdash;it was well past midnight when Jam heard the studio door creak open. She stared into the velvet black of her room and listened to her mother&rsquo;s footsteps walking in her [mother] and Aloe&rsquo;s bedroom. There was a weight thrumming through the floorboards in a low song, and that was how Jam knew the painting was done. <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">Bitter&rsquo;s feet were singing the news.</span></p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2019 by Akwaeke Emezi</span></p>$SATQ$, $SATQ$<p>Which choice best states the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"5c85d27e-3adb-4f5c-b312-49769980bf42","content":"<p>It indicates that Jam is more interested in music than in art.</p>"},{"id":"1567213c-90c3-4e38-b32b-8b6a5606c970","content":"<p>It adds to the idea that Bitter&rsquo;s footsteps reveal something to Jam.</p>"},{"id":"440bd83f-bd64-4352-bf55-f5a2e920fce7","content":"<p>It indicates that Bitter always sings when working on a painting.</p>"},{"id":"25ad2e9e-9364-441d-b9cd-69500ca9a9b9","content":"<p>It describes Aloe&rsquo;s reaction upon seeing the painting for the first time.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["1567213c-90c3-4e38-b32b-8b6a5606c970"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The text establishes that Jam hears Bitter&rsquo;s studio door open early in the morning, when it is still dark. Jam then listens to her mother&rsquo;s footsteps, which seem to create a song that runs through the floorboards. The text indicates that the sound of Bitter&rsquo;s footsteps convey to Jam that Bitter is done painting. The underlined sentence then builds on this idea, stating explicitly that Bitter&rsquo;s feet sing the news of her completion of a painting. Thus, the sentence stating that &ldquo;Bitter&rsquo;s feet were singing the news&rdquo; further emphasizes that Bitter&rsquo;s footsteps themselves reveal information to Jam.</p><p>Choice A is incorrect because the text provides no evidence that Jam prefers music to art. While the underlined sentence uses musical imagery to describe the vibrations Jam feels, this is figurative language that is describing the footsteps&rsquo; vibrations; it isn&rsquo;t an indication of Jam&rsquo;s personal interests. Choice C is incorrect because the text doesn&rsquo;t suggest that Bitter herself sings while working on paintings. The references to singing in the text are figurative descriptions of how Bitter&rsquo;s footsteps sound or feel to Jam, not literal statements about Bitter singing. Choice D is incorrect because the underlined sentence only describes Jam&rsquo;s perception of her mother&rsquo;s footsteps. It doesn&rsquo;t provide any details about Aloe or his reaction to the painting; in fact, the text doesn&rsquo;t mention Aloe seeing the painting at all.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"271a5017","external_id":"9cd9bd44-1c9d-4da9-b40a-e9c317cdd49d","vaultid":null,"uId":"6d70bfea-0a70-43fa-9768-6b4f9cb37b73","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Akwaeke Emezi&rsquo;s 2019 novel <em>Pet</em>. Jam is a teenager who lives with her father, Aloe, and her mother, Bitter, who is a painter.</p>\n<blockquote>\n<p>Bitter finished the painting in the dark morning of a day&mdash;it was well past midnight when Jam heard the studio door creak open. She stared into the velvet black of her room and listened to her mother&rsquo;s footsteps walking in her [mother] and Aloe&rsquo;s bedroom. There was a weight thrumming through the floorboards in a low song, and that was how Jam knew the painting was done. <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">Bitter&rsquo;s feet were singing the news.</span></p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2019 by Akwaeke Emezi</span></p>","stem":"<p>Which choice best states the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"5c85d27e-3adb-4f5c-b312-49769980bf42","content":"<p>It indicates that Jam is more interested in music than in art.</p>"},{"id":"1567213c-90c3-4e38-b32b-8b6a5606c970","content":"<p>It adds to the idea that Bitter&rsquo;s footsteps reveal something to Jam.</p>"},{"id":"440bd83f-bd64-4352-bf55-f5a2e920fce7","content":"<p>It indicates that Bitter always sings when working on a painting.</p>"},{"id":"25ad2e9e-9364-441d-b9cd-69500ca9a9b9","content":"<p>It describes Aloe&rsquo;s reaction upon seeing the painting for the first time.</p>"}],"keys":["1567213c-90c3-4e38-b32b-8b6a5606c970"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The text establishes that Jam hears Bitter&rsquo;s studio door open early in the morning, when it is still dark. Jam then listens to her mother&rsquo;s footsteps, which seem to create a song that runs through the floorboards. The text indicates that the sound of Bitter&rsquo;s footsteps convey to Jam that Bitter is done painting. The underlined sentence then builds on this idea, stating explicitly that Bitter&rsquo;s feet sing the news of her completion of a painting. Thus, the sentence stating that &ldquo;Bitter&rsquo;s feet were singing the news&rdquo; further emphasizes that Bitter&rsquo;s footsteps themselves reveal information to Jam.</p><p>Choice A is incorrect because the text provides no evidence that Jam prefers music to art. While the underlined sentence uses musical imagery to describe the vibrations Jam feels, this is figurative language that is describing the footsteps&rsquo; vibrations; it isn&rsquo;t an indication of Jam&rsquo;s personal interests. Choice C is incorrect because the text doesn&rsquo;t suggest that Bitter herself sings while working on paintings. The references to singing in the text are figurative descriptions of how Bitter&rsquo;s footsteps sound or feel to Jam, not literal statements about Bitter singing. Choice D is incorrect because the underlined sentence only describes Jam&rsquo;s perception of her mother&rsquo;s footsteps. It doesn&rsquo;t provide any details about Aloe or his reaction to the painting; in fact, the text doesn&rsquo;t mention Aloe seeing the painting at all.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$27d9bb69$SATQ$, $SATQ$948cb05c-3a22-4bd0-8f73-3b8087dae9b2$SATQ$::uuid, $SATQ$29764419-f769-44b8-a4c2-6d6d70d2e507$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Text 1</p>
<p>Many studies in psychology have shown that people seek out information even when they know in advance that they have no immediate use for it and that they won&rsquo;t directly benefit from it. Such findings support the consensus view among researchers of curiosity: namely, that curiosity is not instrumental but instead represents a drive to acquire information for its own sake.</p>
<p>Text 2</p>
<p>While acknowledging that acquiring information is a powerful motivator, Rachit Dubey and colleagues ran an experiment to test whether emphasizing the usefulness of scientific information could increase curiosity about it. They found that when research involving rats and fruit flies was presented as having medical applications for humans, participants expressed greater interest in learning about it than when the research was not presented as useful.</p>$SATQ$, $SATQ$<p>Based on the texts, how would Dubey and colleagues (Text 2) most likely respond to the consensus view discussed in Text 1?</p>$SATQ$, $SATQ$[{"id":"0842b305-efe2-42bb-bd0f-40463e419749","content":"<p>By suggesting that curiosity may not be exclusively motivated by the desire to merely acquire information&nbsp; &nbsp;</p>"},{"id":"b036e35d-2f55-4aa5-bcd8-d5c6ed875464","content":"<p>By conceding that people may seek out information that serves no immediate purpose only because they think they can use it later &nbsp;&nbsp; &nbsp;</p>"},{"id":"298d3d4a-d7e9-42fc-9326-fe2b0ea86f6a","content":"<p>By pointing out that it is challenging to determine when information-seeking serves no goal beyond acquiring information</p>"},{"id":"8951939a-a227-4c76-a304-58b2788e5037","content":"<p>By disputing the idea that curiosity can help explain apparently purposeless information-seeking behaviors</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["0842b305-efe2-42bb-bd0f-40463e419749"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The researchers in Text 2 recognize that acquiring information is a powerful motivator, but showed that this motivation can still be affected by other factors, like whether or not the information is expected to be useful or not. This suggests that other desires may play a part in driving people to acquire information. </p><p>Choice B is incorrect. The consensus view in Text 1 is that people acquire information regardless of whether they think they can use it later. Dubey and colleagues acknowledge this fact (so they don&rsquo;t claim people seek out information &ldquo;only&rdquo; because it might be useful later). Choice C is incorrect. This choice misreads the results of Dubey and colleagues&rsquo; study in Text 2. Neither text discusses the difficulty of determining the motivation for information-seeking. Choice D is incorrect. This choice contradicts Text 2, which starts with Dubey and colleagues &ldquo;acknowledging that acquiring information is a powerful motivator&rdquo; (i.e., agreeing that curiosity explains the seeking of apparently purposeless information). The research in Text 2 simply suggests that more than just curiosity can motivate information-seeking behavior when the information has a purpose. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M008$SATQ$, $SATQ$$SATQ$, $SATQ$49999f64-85fa-4db1-b9ca-25f65b168aaa$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"27d9bb69","external_id":"948cb05c-3a22-4bd0-8f73-3b8087dae9b2","vaultid":"29764419-f769-44b8-a4c2-6d6d70d2e507","uId":"d0716324-b2c0-4368-97df-ccd18089ee4c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Text 1</p>\n<p>Many studies in psychology have shown that people seek out information even when they know in advance that they have no immediate use for it and that they won&rsquo;t directly benefit from it. Such findings support the consensus view among researchers of curiosity: namely, that curiosity is not instrumental but instead represents a drive to acquire information for its own sake.</p>\n<p>Text 2</p>\n<p>While acknowledging that acquiring information is a powerful motivator, Rachit Dubey and colleagues ran an experiment to test whether emphasizing the usefulness of scientific information could increase curiosity about it. They found that when research involving rats and fruit flies was presented as having medical applications for humans, participants expressed greater interest in learning about it than when the research was not presented as useful.</p>","stem":"<p>Based on the texts, how would Dubey and colleagues (Text 2) most likely respond to the consensus view discussed in Text 1?</p>","answerOptions":[{"id":"0842b305-efe2-42bb-bd0f-40463e419749","content":"<p>By suggesting that curiosity may not be exclusively motivated by the desire to merely acquire information&nbsp; &nbsp;</p>"},{"id":"b036e35d-2f55-4aa5-bcd8-d5c6ed875464","content":"<p>By conceding that people may seek out information that serves no immediate purpose only because they think they can use it later &nbsp;&nbsp; &nbsp;</p>"},{"id":"298d3d4a-d7e9-42fc-9326-fe2b0ea86f6a","content":"<p>By pointing out that it is challenging to determine when information-seeking serves no goal beyond acquiring information</p>"},{"id":"8951939a-a227-4c76-a304-58b2788e5037","content":"<p>By disputing the idea that curiosity can help explain apparently purposeless information-seeking behaviors</p>"}],"keys":["0842b305-efe2-42bb-bd0f-40463e419749"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The researchers in Text 2 recognize that acquiring information is a powerful motivator, but showed that this motivation can still be affected by other factors, like whether or not the information is expected to be useful or not. This suggests that other desires may play a part in driving people to acquire information. </p><p>Choice B is incorrect. The consensus view in Text 1 is that people acquire information regardless of whether they think they can use it later. Dubey and colleagues acknowledge this fact (so they don&rsquo;t claim people seek out information &ldquo;only&rdquo; because it might be useful later). Choice C is incorrect. This choice misreads the results of Dubey and colleagues&rsquo; study in Text 2. Neither text discusses the difficulty of determining the motivation for information-seeking. Choice D is incorrect. This choice contradicts Text 2, which starts with Dubey and colleagues &ldquo;acknowledging that acquiring information is a powerful motivator&rdquo; (i.e., agreeing that curiosity explains the seeking of apparently purposeless information). The research in Text 2 simply suggests that more than just curiosity can motivate information-seeking behavior when the information has a purpose. </p>","parenttemplatename":"OSP-KA-CTC-M008","parenttemplateid":"","templateclusterid":"49999f64-85fa-4db1-b9ca-25f65b168aaa","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$2903a041$SATQ$, $SATQ$43ecabea-3f8f-4b48-8e5d-80853f68cd2f$SATQ$::uuid, $SATQ$a48316e7-49d0-4b02-aec9-1d957d5ade5c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Using NASA&rsquo;s powerful James Webb Space Telescope (JWST), Mercedes L&oacute;pez-Morales and colleagues measured the wavelengths of light traveling through the atmosphere of WASP-39b, an exoplanet, or planet outside our solar system. Different molecules absorb different wavelengths of light, and the wavelength measurements showed the presence of carbon dioxide (CO₂) in WASP-39b&rsquo;s atmosphere. This finding not only offers the first decisive evidence of CO₂ in the atmosphere of an exoplanet but also illustrates the potential for future scientific breakthroughs held by the JWST.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"1fb40737-ec07-4616-b507-3bfdc8de2fcb","content":"<p>It discusses a method used by some researchers, then states why an alternative method is superior to it.</p>"},{"id":"286ec4b4-a82d-4117-9be3-c996a323031b","content":"<p>It describes how researchers made a scientific discovery, then explains the importance of that discovery.</p>"},{"id":"03ac5f7d-ab5f-4da0-959e-9fca7737ecd0","content":"<p>It outlines the steps taken in a scientific study, then presents a hypothesis based on that study.</p>"},{"id":"9d9e6710-e52b-4111-9c9d-9ac827452899","content":"<p>It examines how a group of scientists reached a conclusion, then shows how other scientists have challenged that conclusion.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["286ec4b4-a82d-4117-9be3-c996a323031b"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The text begins by describing how the researchers used the JWST to detect CO₂ in WASP-39b&rsquo;s atmosphere. Then the text discusses the significance of this finding, both as the first evidence of CO₂ in an exoplanet&rsquo;s atmosphere and as an illustration of the JWST&rsquo;s potential for making new discoveries in general. </p><p>Choice A is incorrect. The text doesn&rsquo;t compare two different methods, but rather focuses on one study that used the JWST. Choice C is incorrect. The text doesn&rsquo;t present a hypothesis, but rather reports on the findings of a study. Choice D is incorrect. The text doesn&rsquo;t mention any scientists challenging the conclusion reached by L&oacute;pez-Morales and colleagues. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-M010$SATQ$, $SATQ$$SATQ$, $SATQ$d6ada45c-49f4-499f-8d4a-af6f7b62ab09$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2903a041","external_id":"43ecabea-3f8f-4b48-8e5d-80853f68cd2f","vaultid":"a48316e7-49d0-4b02-aec9-1d957d5ade5c","uId":"1b7212bd-9d4c-4b33-99ae-05ced7a6728f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Using NASA&rsquo;s powerful James Webb Space Telescope (JWST), Mercedes L&oacute;pez-Morales and colleagues measured the wavelengths of light traveling through the atmosphere of WASP-39b, an exoplanet, or planet outside our solar system. Different molecules absorb different wavelengths of light, and the wavelength measurements showed the presence of carbon dioxide (CO₂) in WASP-39b&rsquo;s atmosphere. This finding not only offers the first decisive evidence of CO₂ in the atmosphere of an exoplanet but also illustrates the potential for future scientific breakthroughs held by the JWST.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"1fb40737-ec07-4616-b507-3bfdc8de2fcb","content":"<p>It discusses a method used by some researchers, then states why an alternative method is superior to it.</p>"},{"id":"286ec4b4-a82d-4117-9be3-c996a323031b","content":"<p>It describes how researchers made a scientific discovery, then explains the importance of that discovery.</p>"},{"id":"03ac5f7d-ab5f-4da0-959e-9fca7737ecd0","content":"<p>It outlines the steps taken in a scientific study, then presents a hypothesis based on that study.</p>"},{"id":"9d9e6710-e52b-4111-9c9d-9ac827452899","content":"<p>It examines how a group of scientists reached a conclusion, then shows how other scientists have challenged that conclusion.</p>"}],"keys":["286ec4b4-a82d-4117-9be3-c996a323031b"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The text begins by describing how the researchers used the JWST to detect CO₂ in WASP-39b&rsquo;s atmosphere. Then the text discusses the significance of this finding, both as the first evidence of CO₂ in an exoplanet&rsquo;s atmosphere and as an illustration of the JWST&rsquo;s potential for making new discoveries in general. </p><p>Choice A is incorrect. The text doesn&rsquo;t compare two different methods, but rather focuses on one study that used the JWST. Choice C is incorrect. The text doesn&rsquo;t present a hypothesis, but rather reports on the findings of a study. Choice D is incorrect. The text doesn&rsquo;t mention any scientists challenging the conclusion reached by L&oacute;pez-Morales and colleagues. </p>","parenttemplatename":"OSP-KA-TSP-M010","parenttemplateid":"","templateclusterid":"d6ada45c-49f4-499f-8d4a-af6f7b62ab09","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$29741ebc$SATQ$, $SATQ$d8f2d55e-1a54-42bc-9c26-4590addf0853$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In the past, historians who wanted to examine Frederick Douglass&rsquo;s diary and other personal papers had to visit the Library of Congress in Washington, DC, to view them on microfilm <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">(film containing scaled-down reproductions of documents)</span>. But traveling to the library often added time and costs to research projects. Now, by going to the library&rsquo;s website, researchers can access digitized versions of Douglass&rsquo;s papers without physically going anywhere.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"1ab79f30-20ee-46c3-b910-71ca4d2d9ea6","content":"<p>It gives information about a famous person.</p>"},{"id":"dfcb9ffc-c724-4437-8a93-40d57f6f19d2","content":"<p>It explains the meaning of a word.</p>"},{"id":"c1d9bc7e-10d7-453c-a4bb-8a4d481e167c","content":"<p>It describes a debate among historians.</p>"},{"id":"73e4923a-7c09-4cde-8e8d-f085a422afbc","content":"<p>It summarizes an unexpected finding.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["dfcb9ffc-c724-4437-8a93-40d57f6f19d2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The underlined portion is a parenthetical phrase directly following the word &ldquo;microfilm,&rdquo; and it describes film containing small (&ldquo;scaled-down&rdquo;) images; the placement and focus of the portion indicate that it is serving to define the term &ldquo;microfilm.&rdquo;</p><p>Choice A is incorrect. Although the text is about accessing the writings of a famous historical figure (Douglass), the underlined portion doesn&rsquo;t give information about Douglass or any other person. Instead, it explains what microfilms are. Choice C is incorrect because the text never describes any kind of debate or disagreement; it simply describes a change in how researchers can access historical documents, with the underlined portion defining an important term. Choice D is incorrect because the text never makes any mention of a particular finding, unexpected or otherwise; it simply describes a change in how researchers do some of their work, with the underlined portion defining an important term.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"29741ebc","external_id":"d8f2d55e-1a54-42bc-9c26-4590addf0853","vaultid":null,"uId":"57b2a2b1-6b7b-4c3e-9048-57d4dede7d1e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In the past, historians who wanted to examine Frederick Douglass&rsquo;s diary and other personal papers had to visit the Library of Congress in Washington, DC, to view them on microfilm <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">(film containing scaled-down reproductions of documents)</span>. But traveling to the library often added time and costs to research projects. Now, by going to the library&rsquo;s website, researchers can access digitized versions of Douglass&rsquo;s papers without physically going anywhere.</p>","stem":"<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"1ab79f30-20ee-46c3-b910-71ca4d2d9ea6","content":"<p>It gives information about a famous person.</p>"},{"id":"dfcb9ffc-c724-4437-8a93-40d57f6f19d2","content":"<p>It explains the meaning of a word.</p>"},{"id":"c1d9bc7e-10d7-453c-a4bb-8a4d481e167c","content":"<p>It describes a debate among historians.</p>"},{"id":"73e4923a-7c09-4cde-8e8d-f085a422afbc","content":"<p>It summarizes an unexpected finding.</p>"}],"keys":["dfcb9ffc-c724-4437-8a93-40d57f6f19d2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The underlined portion is a parenthetical phrase directly following the word &ldquo;microfilm,&rdquo; and it describes film containing small (&ldquo;scaled-down&rdquo;) images; the placement and focus of the portion indicate that it is serving to define the term &ldquo;microfilm.&rdquo;</p><p>Choice A is incorrect. Although the text is about accessing the writings of a famous historical figure (Douglass), the underlined portion doesn&rsquo;t give information about Douglass or any other person. Instead, it explains what microfilms are. Choice C is incorrect because the text never describes any kind of debate or disagreement; it simply describes a change in how researchers can access historical documents, with the underlined portion defining an important term. Choice D is incorrect because the text never makes any mention of a particular finding, unexpected or otherwise; it simply describes a change in how researchers do some of their work, with the underlined portion defining an important term.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$2aaee77f$SATQ$, $SATQ$21e6d1f4-15ed-49a1-87c9-cbcd3f0b78ed$SATQ$::uuid, $SATQ$fe7e29db-05c8-44a8-b294-7eb04d3cddfd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Some bird species don&rsquo;t raise their own chicks. Instead, adult females lay their eggs in other nests, next to another bird species&rsquo; own eggs. <span role="region" aria-label="Referenced Content"><u>Female cuckoos have been seen quickly laying eggs in the nests of other bird species when those birds are out looking for food.</u></span> After the eggs hatch, the noncuckoo parents will typically raise the cuckoo chicks as if they were their own offspring, even if the cuckoos look very different from the other chicks.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"3f87a11f-33e7-445f-88c3-34b71ed20db3","content":"<p>It introduces a physical feature of female cuckoos that is described later in the text.</p>"},{"id":"fedb7cbe-ba84-4bc8-9c76-58bfea690aa5","content":"<p>It describes the appearance of the cuckoo nests mentioned earlier in the text.</p>"},{"id":"e5bb6f6b-ffb2-4112-9571-2c1ac9f5e232","content":"<p>It offers a detail about how female cuckoos carry out the behavior discussed in the text.</p>"},{"id":"d654635d-bc33-4d0e-840a-2e9d1199560c","content":"<p>It explains how other birds react to the female cuckoo behavior discussed in the text.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["e5bb6f6b-ffb2-4112-9571-2c1ac9f5e232"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it best describes how the underlined sentence functions in the text as a whole. The first two sentences establish that birds of some species don&rsquo;t raise their own young; instead, they lay their eggs in the nests of birds of other species. The underlined sentence then states that female cuckoo birds engage in this behavior, having been observed specifically laying their eggs in other nests while the other birds are out finding food. According to the text, the cuckoo chicks are then raised by the other birds. Thus, the underlined sentence provides a particular detail about how female cuckoos carry out the behavior of laying eggs for other birds to raise. </p><p>Choice A is incorrect. Rather than mentioning a physical feature of female cuckoos, the underlined sentence introduces a specific behavior of female cuckoos: laying eggs in the nests of birds of other species when the other birds are away. The only reference to physical features is the last sentence&rsquo;s general mention of cuckoo chicks looking different from chicks of other species. Choice B is incorrect because the underlined sentence refers to the nests of birds other than cuckoos and doesn&rsquo;t describe how any nests look, cuckoo or otherwise. Instead, the sentence addresses how female cuckoos use other birds&rsquo; nests. Choice D is incorrect because the underlined sentence describes only female cuckoo behavior (laying eggs in the nests of birds of other species when the other birds are away); it&rsquo;s the last sentence of the text that addresses the other birds&rsquo; reaction, indicating that those birds usually raise the cuckoo chicks once they&rsquo;ve hatched.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-005-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$51384c76-2b35-4a7b-a50d-5bdc49f2aeff$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2aaee77f","external_id":"21e6d1f4-15ed-49a1-87c9-cbcd3f0b78ed","vaultid":"fe7e29db-05c8-44a8-b294-7eb04d3cddfd","uId":"4ddfe9f8-17bc-4b2a-8529-78df75ad8daa","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Some bird species don&rsquo;t raise their own chicks. Instead, adult females lay their eggs in other nests, next to another bird species&rsquo; own eggs. <span role=\"region\" aria-label=\"Referenced Content\"><u>Female cuckoos have been seen quickly laying eggs in the nests of other bird species when those birds are out looking for food.</u></span> After the eggs hatch, the noncuckoo parents will typically raise the cuckoo chicks as if they were their own offspring, even if the cuckoos look very different from the other chicks.</p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"3f87a11f-33e7-445f-88c3-34b71ed20db3","content":"<p>It introduces a physical feature of female cuckoos that is described later in the text.</p>"},{"id":"fedb7cbe-ba84-4bc8-9c76-58bfea690aa5","content":"<p>It describes the appearance of the cuckoo nests mentioned earlier in the text.</p>"},{"id":"e5bb6f6b-ffb2-4112-9571-2c1ac9f5e232","content":"<p>It offers a detail about how female cuckoos carry out the behavior discussed in the text.</p>"},{"id":"d654635d-bc33-4d0e-840a-2e9d1199560c","content":"<p>It explains how other birds react to the female cuckoo behavior discussed in the text.</p>"}],"keys":["e5bb6f6b-ffb2-4112-9571-2c1ac9f5e232"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it best describes how the underlined sentence functions in the text as a whole. The first two sentences establish that birds of some species don&rsquo;t raise their own young; instead, they lay their eggs in the nests of birds of other species. The underlined sentence then states that female cuckoo birds engage in this behavior, having been observed specifically laying their eggs in other nests while the other birds are out finding food. According to the text, the cuckoo chicks are then raised by the other birds. Thus, the underlined sentence provides a particular detail about how female cuckoos carry out the behavior of laying eggs for other birds to raise. </p><p>Choice A is incorrect. Rather than mentioning a physical feature of female cuckoos, the underlined sentence introduces a specific behavior of female cuckoos: laying eggs in the nests of birds of other species when the other birds are away. The only reference to physical features is the last sentence&rsquo;s general mention of cuckoo chicks looking different from chicks of other species. Choice B is incorrect because the underlined sentence refers to the nests of birds other than cuckoos and doesn&rsquo;t describe how any nests look, cuckoo or otherwise. Instead, the sentence addresses how female cuckoos use other birds&rsquo; nests. Choice D is incorrect because the underlined sentence describes only female cuckoo behavior (laying eggs in the nests of birds of other species when the other birds are away); it&rsquo;s the last sentence of the text that addresses the other birds&rsquo; reaction, indicating that those birds usually raise the cuckoo chicks once they&rsquo;ve hatched.&nbsp;</p>","parenttemplatename":"OSP-005-TSP","parenttemplateid":"","templateclusterid":"51384c76-2b35-4a7b-a50d-5bdc49f2aeff","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959312,"updateDate":1691007959312}$SATQ$::jsonb, 1691007959312, 1691007959312),
    ($SATQ$2af2016f$SATQ$, $SATQ$86f1dfca-37f3-4b19-a864-e405655f0e34$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>A study by Dr. Paul Hanel and colleagues concluded that people are more likely to behave politely when listening to ideas they disagree with if they think about values before they engage in a discussion. Study participants were assigned to one of two groups. The experimental group spent a few minutes writing about one of their personal values before they had a group discussion on a controversial topic. And the control group spent a few minutes writing about a drink (tea, milk, etc.) before their group discussion on that topic. Hanel and colleagues found that the experimental group&rsquo;s discussion was more civil than the control group&rsquo;s discussion was.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice best describes the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"e0630551-3c04-4c23-b200-51aeed316fb1","content":"<p>To describe a widely held belief and how a study&rsquo;s results support that belief</p>"},{"id":"bee5b768-9d9c-4b8c-be98-6a2696e5f36b","content":"<p>To argue that researchers were surprised by the results of a certain study</p>"},{"id":"9a0dc679-89c9-4821-9c7f-2a050d7ff937","content":"<p>To suggest ways to improve a certain study&rsquo;s experimental design</p>"},{"id":"0d00ee00-f469-4937-ab63-aeefbef1c5ea","content":"<p>To explain a study&rsquo;s conclusion and how a research team arrived at that conclusion</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0d00ee00-f469-4937-ab63-aeefbef1c5ea"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately describes the main purpose of the text, which is to explain a study&rsquo;s conclusion and how researchers involved in the study arrived at that conclusion. The text begins by summarizing the main conclusion of the study conducted by Paul Hanel and colleagues: when confronted with ideas they disagree with in discussions about controversial topics, people are more likely to respond politely if they think about their personal values before engaging in such discussions. The text then goes on to describe the design of Hanel and colleagues&rsquo; experiment. By comparing interactions between members of an experimental group (who had been prompted to write about their personal values beforehand) to those between members of a control group (who had been prompted to write about a beverage), the team found that people in the experimental group behaved more civilly, or politely, than people in the control group did during discussions about a controversial topic. This finding led to the conclusion described at the beginning of the text.</p><p>Choice A is incorrect. Although the text discusses the results of a study, it doesn&rsquo;t provide any indication that the conclusion the study supported&mdash;that when facing disagreement, people behave more politely when they have thought about their values&mdash;is a belief that is widely held. Choice B is incorrect because the text doesn&rsquo;t indicate that the researchers found the results of their study to be surprising, or contrary to what they expected. In fact, there&rsquo;s no indication provided in the text about how the researchers felt about the study&rsquo;s results or that the results should be considered surprising. Choice C is incorrect. Although the text discusses the experimental design of a study, it doesn&rsquo;t suggest any improvements to that design; instead, it focuses on how the design enabled the researchers to draw a particular conclusion.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2af2016f","external_id":"86f1dfca-37f3-4b19-a864-e405655f0e34","vaultid":null,"uId":"0933d0e5-0612-448b-8d36-60bce5520e55","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>A study by Dr. Paul Hanel and colleagues concluded that people are more likely to behave politely when listening to ideas they disagree with if they think about values before they engage in a discussion. Study participants were assigned to one of two groups. The experimental group spent a few minutes writing about one of their personal values before they had a group discussion on a controversial topic. And the control group spent a few minutes writing about a drink (tea, milk, etc.) before their group discussion on that topic. Hanel and colleagues found that the experimental group&rsquo;s discussion was more civil than the control group&rsquo;s discussion was.&nbsp;</p>","stem":"<p>Which choice best describes the main purpose of the text?</p>","answerOptions":[{"id":"e0630551-3c04-4c23-b200-51aeed316fb1","content":"<p>To describe a widely held belief and how a study&rsquo;s results support that belief</p>"},{"id":"bee5b768-9d9c-4b8c-be98-6a2696e5f36b","content":"<p>To argue that researchers were surprised by the results of a certain study</p>"},{"id":"9a0dc679-89c9-4821-9c7f-2a050d7ff937","content":"<p>To suggest ways to improve a certain study&rsquo;s experimental design</p>"},{"id":"0d00ee00-f469-4937-ab63-aeefbef1c5ea","content":"<p>To explain a study&rsquo;s conclusion and how a research team arrived at that conclusion</p>"}],"keys":["0d00ee00-f469-4937-ab63-aeefbef1c5ea"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately describes the main purpose of the text, which is to explain a study&rsquo;s conclusion and how researchers involved in the study arrived at that conclusion. The text begins by summarizing the main conclusion of the study conducted by Paul Hanel and colleagues: when confronted with ideas they disagree with in discussions about controversial topics, people are more likely to respond politely if they think about their personal values before engaging in such discussions. The text then goes on to describe the design of Hanel and colleagues&rsquo; experiment. By comparing interactions between members of an experimental group (who had been prompted to write about their personal values beforehand) to those between members of a control group (who had been prompted to write about a beverage), the team found that people in the experimental group behaved more civilly, or politely, than people in the control group did during discussions about a controversial topic. This finding led to the conclusion described at the beginning of the text.</p><p>Choice A is incorrect. Although the text discusses the results of a study, it doesn&rsquo;t provide any indication that the conclusion the study supported&mdash;that when facing disagreement, people behave more politely when they have thought about their values&mdash;is a belief that is widely held. Choice B is incorrect because the text doesn&rsquo;t indicate that the researchers found the results of their study to be surprising, or contrary to what they expected. In fact, there&rsquo;s no indication provided in the text about how the researchers felt about the study&rsquo;s results or that the results should be considered surprising. Choice C is incorrect. Although the text discusses the experimental design of a study, it doesn&rsquo;t suggest any improvements to that design; instead, it focuses on how the design enabled the researchers to draw a particular conclusion.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323041,"updateDate":1730147323041}$SATQ$::jsonb, 1730147323041, 1730147323041),
    ($SATQ$2b085bc6$SATQ$, $SATQ$e7bb11cb-8c17-4290-bd1b-5ffba54bbdbe$SATQ$::uuid, $SATQ$d8308dbd-59bf-43c1-a99b-75e6946c286e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Paul Laurence Dunbar&rsquo;s 1902 novel <em>The Sport of the Gods</em>. Joe and some of his family members have recently moved to New York City.</p>
<blockquote>
<p>[Joe] was wild with enthusiasm and with a desire to be a part of all that the metropolis meant. In the evening he saw the young fellows passing by dressed in their spruce clothes, and he wondered with a sort of envy where they could be going. Back home there had been no place much worth going to, except church and one or two people&rsquo;s houses.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"5d7efa2e-f2fc-4772-92e5-f1f62ac523fc","content":"<p>It illustrates a character&rsquo;s reaction to a new environment.</p>"},{"id":"0e5553a2-ec88-4a88-8e7b-e8c677002f28","content":"<p>It explains why a character has traveled to a city.</p>"},{"id":"92332796-7860-4092-aa47-249ed2bb6077","content":"<p>It compares a character&rsquo;s thoughts about an event at two different times of day.</p>"},{"id":"9276482c-ac16-458f-a0a3-c7b6667c20f8","content":"<p>It presents a character feeling regret over leaving home.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5d7efa2e-f2fc-4772-92e5-f1f62ac523fc"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes the main purpose of the text. The narrator describes how Joe responds to being in &ldquo;the metropolis&rdquo;: he&rsquo;s excited and &ldquo;wild with enthusiasm.&rdquo; He also envies the young fellows who walk by because, dressed as they are, they look as if they have somewhere special to go. The text contrasts this new place with the place Joe comes from, where apparently there wasn&rsquo;t as much to do. Thus, the main purpose of the text is to illustrate Joe&rsquo;s reaction to a new environment. </p><p>Choice B is incorrect because the text makes no reference to why Joe has moved. The narrator indicates that Joe is enthusiastic about being in a city, but there&rsquo;s no explanation provided for the move.&nbsp;Choice C is incorrect because the text makes no reference to how Joe thinks about an event. The narrator describes young men passing by in the evening and then recalls places worth going to at home&mdash;church and a few people&rsquo;s houses&mdash;but there&rsquo;s no explicit comparison made nor is a time of day mentioned for these events back home. Choice D is incorrect because the text doesn&rsquo;t support the idea that Joe feels regret over leaving home. Instead, Joe is described as &ldquo;wild with enthusiasm&rdquo; at being in the city. Joe&rsquo;s home is mentioned, but only to compare it unfavorably with the city. </p>$SATQ$, false, 0, $SATQ$OSP-047-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$cec851c5-2cf0-4374-a7d7-0951df5edd89$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2b085bc6","external_id":"e7bb11cb-8c17-4290-bd1b-5ffba54bbdbe","vaultid":"d8308dbd-59bf-43c1-a99b-75e6946c286e","uId":"6a6b1ad3-4428-4275-82f3-bd2d09419e44","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is adapted from Paul Laurence Dunbar&rsquo;s 1902 novel <em>The Sport of the Gods</em>. Joe and some of his family members have recently moved to New York City.</p>\n<blockquote>\n<p>[Joe] was wild with enthusiasm and with a desire to be a part of all that the metropolis meant. In the evening he saw the young fellows passing by dressed in their spruce clothes, and he wondered with a sort of envy where they could be going. Back home there had been no place much worth going to, except church and one or two people&rsquo;s houses.</p>\n</blockquote>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"5d7efa2e-f2fc-4772-92e5-f1f62ac523fc","content":"<p>It illustrates a character&rsquo;s reaction to a new environment.</p>"},{"id":"0e5553a2-ec88-4a88-8e7b-e8c677002f28","content":"<p>It explains why a character has traveled to a city.</p>"},{"id":"92332796-7860-4092-aa47-249ed2bb6077","content":"<p>It compares a character&rsquo;s thoughts about an event at two different times of day.</p>"},{"id":"9276482c-ac16-458f-a0a3-c7b6667c20f8","content":"<p>It presents a character feeling regret over leaving home.</p>"}],"keys":["5d7efa2e-f2fc-4772-92e5-f1f62ac523fc"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes the main purpose of the text. The narrator describes how Joe responds to being in &ldquo;the metropolis&rdquo;: he&rsquo;s excited and &ldquo;wild with enthusiasm.&rdquo; He also envies the young fellows who walk by because, dressed as they are, they look as if they have somewhere special to go. The text contrasts this new place with the place Joe comes from, where apparently there wasn&rsquo;t as much to do. Thus, the main purpose of the text is to illustrate Joe&rsquo;s reaction to a new environment. </p><p>Choice B is incorrect because the text makes no reference to why Joe has moved. The narrator indicates that Joe is enthusiastic about being in a city, but there&rsquo;s no explanation provided for the move.&nbsp;Choice C is incorrect because the text makes no reference to how Joe thinks about an event. The narrator describes young men passing by in the evening and then recalls places worth going to at home&mdash;church and a few people&rsquo;s houses&mdash;but there&rsquo;s no explicit comparison made nor is a time of day mentioned for these events back home. Choice D is incorrect because the text doesn&rsquo;t support the idea that Joe feels regret over leaving home. Instead, Joe is described as &ldquo;wild with enthusiasm&rdquo; at being in the city. Joe&rsquo;s home is mentioned, but only to compare it unfavorably with the city. </p>","parenttemplatename":"OSP-047-TSP","parenttemplateid":"","templateclusterid":"cec851c5-2cf0-4374-a7d7-0951df5edd89","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959323,"updateDate":1691007959323}$SATQ$::jsonb, 1691007959323, 1691007959323),
    ($SATQ$2c50ed1a$SATQ$, $SATQ$1c5a0f46-361b-4d1f-9fd8-82df4dc8295a$SATQ$::uuid, $SATQ$fc46b40b-1ff8-4364-87ac-74c4b388fb5e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><strong>Text 1</strong></p>
<p>Literary scholars have struggled with the vastness of Nigerian writer Wole Soyinka&rsquo;s collective works of drama (spanning over 20 plays in total). It is best, however, to understand Soyinka&rsquo;s body of work as a dramatist chronologically. Soyinka&rsquo;s progression as a playwright can be considered to fall into three periods, with each one representing a particular thematic and stylistic cohesion: the 1960s, the two decades between 1970 and 1990, and lastly, from roughly 1990 onwards.&nbsp;</p>
<p>&nbsp;</p>
<p><strong>Text 2</strong>&nbsp;</p>
<p>It is tempting to impose a linear sense of order on the expanse of Wole Soyinka&rsquo;s body of work as a dramatist. However, critics who have considered Soyinka&rsquo;s plays to fit neatly into three phases overlook potential commonalities in Soyinka&rsquo;s work that span across these phases. Additionally, this view may discount significant differences in the styles and content of plays written around the same time.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice best describes a difference in how the author of Text 1 and the author of Text 2 view the study of Soyinka&rsquo;s works of drama?</p>$SATQ$, $SATQ$[{"id":"24dcc6b8-25c4-42b7-a68a-23f2af953123","content":"<p>While the author of Text 1 believes that thinking about Soyinka&rsquo;s works of theater in phases is useful, the author of Text 2 views such an approach as limiting.</p>"},{"id":"91936ec9-09b7-4d6a-85c7-18447bdfc0d7","content":"<p>Although the author of Text 1 claims that Soyinka&rsquo;s style as a dramatist has evolved over time, the author of Text 2 argues that Soyinka&rsquo;s style has remained consistent throughout his career.</p>"},{"id":"86944d90-276f-4462-b9f4-0c468342a2e7","content":"<p>The author of Text 1 considers Soyinka&rsquo;s plays to showcase his strongest writing, whereas the author of Text 2 believes that Soyinka&rsquo;s poetry is where he is most skilled.</p>"},{"id":"680cc798-ab81-4812-af52-4c16507edc89","content":"<p>The author of Text 1 argues that Soyinka&rsquo;s early plays were his most politically charged, whereas the author of Text 2 claims that Soyinka&rsquo;s most recent plays are the most politicized.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["24dcc6b8-25c4-42b7-a68a-23f2af953123"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The author of Text 1 states that Soyinka&rsquo;s progression as a playwright can be considered to fall into three periods, implying that this is a helpful way to understand his works. The author of Text 2, on the other hand, challenges this view and says that it overlooks potential commonalities and differences in Soyinka&rsquo;s work across what Text 1 calls distinctive stylistic phases. </p><p>Choice B is incorrect. This choice overstates the central claim of Text 2. The author of Text 2 argues against the chronological progression supported in Text 1, but does not go so far as to say that Soyinka&rsquo;s style remained consistent. In fact, Text 2 points out &ldquo;significant differences in styles and content&rdquo; among Soyinka&rsquo;s plays. Choice C is incorrect. Neither of the texts mention Soyinka&rsquo;s poetry, nor do they rank his dramatic writing relative to his other work. Choice D is incorrect. Neither text discusses the political aspects of Soyinka&rsquo;s plays, nor do they make any claims about whether they have changed over time. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M005$SATQ$, $SATQ$$SATQ$, $SATQ$389bb76c-c4cf-45b7-a0d1-c2535357dc21$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"2c50ed1a","external_id":"1c5a0f46-361b-4d1f-9fd8-82df4dc8295a","vaultid":"fc46b40b-1ff8-4364-87ac-74c4b388fb5e","uId":"ac8263c5-f0f6-4da3-9091-87cbce8aecb4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><strong>Text 1</strong></p>\n<p>Literary scholars have struggled with the vastness of Nigerian writer Wole Soyinka&rsquo;s collective works of drama (spanning over 20 plays in total). It is best, however, to understand Soyinka&rsquo;s body of work as a dramatist chronologically. Soyinka&rsquo;s progression as a playwright can be considered to fall into three periods, with each one representing a particular thematic and stylistic cohesion: the 1960s, the two decades between 1970 and 1990, and lastly, from roughly 1990 onwards.&nbsp;</p>\n<p>&nbsp;</p>\n<p><strong>Text 2</strong>&nbsp;</p>\n<p>It is tempting to impose a linear sense of order on the expanse of Wole Soyinka&rsquo;s body of work as a dramatist. However, critics who have considered Soyinka&rsquo;s plays to fit neatly into three phases overlook potential commonalities in Soyinka&rsquo;s work that span across these phases. Additionally, this view may discount significant differences in the styles and content of plays written around the same time.&nbsp;</p>","stem":"<p>Which choice best describes a difference in how the author of Text 1 and the author of Text 2 view the study of Soyinka&rsquo;s works of drama?</p>","answerOptions":[{"id":"24dcc6b8-25c4-42b7-a68a-23f2af953123","content":"<p>While the author of Text 1 believes that thinking about Soyinka&rsquo;s works of theater in phases is useful, the author of Text 2 views such an approach as limiting.</p>"},{"id":"91936ec9-09b7-4d6a-85c7-18447bdfc0d7","content":"<p>Although the author of Text 1 claims that Soyinka&rsquo;s style as a dramatist has evolved over time, the author of Text 2 argues that Soyinka&rsquo;s style has remained consistent throughout his career.</p>"},{"id":"86944d90-276f-4462-b9f4-0c468342a2e7","content":"<p>The author of Text 1 considers Soyinka&rsquo;s plays to showcase his strongest writing, whereas the author of Text 2 believes that Soyinka&rsquo;s poetry is where he is most skilled.</p>"},{"id":"680cc798-ab81-4812-af52-4c16507edc89","content":"<p>The author of Text 1 argues that Soyinka&rsquo;s early plays were his most politically charged, whereas the author of Text 2 claims that Soyinka&rsquo;s most recent plays are the most politicized.</p>"}],"keys":["24dcc6b8-25c4-42b7-a68a-23f2af953123"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The author of Text 1 states that Soyinka&rsquo;s progression as a playwright can be considered to fall into three periods, implying that this is a helpful way to understand his works. The author of Text 2, on the other hand, challenges this view and says that it overlooks potential commonalities and differences in Soyinka&rsquo;s work across what Text 1 calls distinctive stylistic phases. </p><p>Choice B is incorrect. This choice overstates the central claim of Text 2. The author of Text 2 argues against the chronological progression supported in Text 1, but does not go so far as to say that Soyinka&rsquo;s style remained consistent. In fact, Text 2 points out &ldquo;significant differences in styles and content&rdquo; among Soyinka&rsquo;s plays. Choice C is incorrect. Neither of the texts mention Soyinka&rsquo;s poetry, nor do they rank his dramatic writing relative to his other work. Choice D is incorrect. Neither text discusses the political aspects of Soyinka&rsquo;s plays, nor do they make any claims about whether they have changed over time. </p>","parenttemplatename":"OSP-KA-CTC-M005","parenttemplateid":"","templateclusterid":"389bb76c-c4cf-45b7-a0d1-c2535357dc21","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$2c82068f$SATQ$, $SATQ$1dd08ff1-78f2-4c00-acbe-78c14edde937$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Mark Oshiro&rsquo;s 2018 novel <em>Anger Is a Gift</em>. In the novel, Moss and his friends are on a subway train in Northern California.&nbsp;</p>
<blockquote>
<p>Lights from the outside world then filled the train car as it rose out of the ground and climbed the elevated track. As long as Moss had lived in West Oakland, he&rsquo;d never tired of this&nbsp;<span style="text-decoration: underline;" role="region" aria-label="Referenced Content">specific</span> view, so he pointed toward the windows. &ldquo;Check it,&rdquo; he said, and the Port of Oakland began to pass by them.&nbsp;</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2018 by Mark Oshiro</span></p>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;specific&rdquo; most nearly mean?</p>$SATQ$, $SATQ$[{"id":"4882a698-ea31-4cd4-8b8a-9d59d5cfea5e","content":"<p>Imaginary</p>"},{"id":"5fbd665f-d216-42ab-8585-6a59e264ed44","content":"<p>Energetic</p>"},{"id":"6bd920f1-0beb-4174-8560-17c438a61677","content":"<p>Correct</p>"},{"id":"01c329e3-1b30-4c55-9a5f-1fd7c5a28b15","content":"<p>Particular</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["01c329e3-1b30-4c55-9a5f-1fd7c5a28b15"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because as used in the text, "specific" most nearly means particular. The text is referring to the particular view of the Port of Oakland as seen from a subway train as it rises from underground. This specific, or particular, view has always been special to Moss, a lifetime resident of West Oakland.</p><p>Choice A is incorrect. Although the text itself is a work of fiction, the view is something Moss can point out to his companions on the train, so the view itself is presumably not imaginary. Choice B is incorrect. Although this view of the Port of Oakland is significant to Moss, nothing in the text describes the view as particularly energetic as opposed to calming, for example. Choice C is incorrect. The point of the text is that the view of the Port of Oakland from the subway train as it rises from underground is significant to Moss, not whether it is described as being correct, which the text does not address.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2c82068f","external_id":"1dd08ff1-78f2-4c00-acbe-78c14edde937","vaultid":null,"uId":"e3e0e437-795c-45d5-b94f-0b4fa51b27a6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The following text is from Mark Oshiro&rsquo;s 2018 novel <em>Anger Is a Gift</em>. In the novel, Moss and his friends are on a subway train in Northern California.&nbsp;</p>\n<blockquote>\n<p>Lights from the outside world then filled the train car as it rose out of the ground and climbed the elevated track. As long as Moss had lived in West Oakland, he&rsquo;d never tired of this&nbsp;<span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">specific</span> view, so he pointed toward the windows. &ldquo;Check it,&rdquo; he said, and the Port of Oakland began to pass by them.&nbsp;</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2018 by Mark Oshiro</span></p>","stem":"<p>As used in the text, what does the word &ldquo;specific&rdquo; most nearly mean?</p>","answerOptions":[{"id":"4882a698-ea31-4cd4-8b8a-9d59d5cfea5e","content":"<p>Imaginary</p>"},{"id":"5fbd665f-d216-42ab-8585-6a59e264ed44","content":"<p>Energetic</p>"},{"id":"6bd920f1-0beb-4174-8560-17c438a61677","content":"<p>Correct</p>"},{"id":"01c329e3-1b30-4c55-9a5f-1fd7c5a28b15","content":"<p>Particular</p>"}],"keys":["01c329e3-1b30-4c55-9a5f-1fd7c5a28b15"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because as used in the text, \"specific\" most nearly means particular. The text is referring to the particular view of the Port of Oakland as seen from a subway train as it rises from underground. This specific, or particular, view has always been special to Moss, a lifetime resident of West Oakland.</p><p>Choice A is incorrect. Although the text itself is a work of fiction, the view is something Moss can point out to his companions on the train, so the view itself is presumably not imaginary. Choice B is incorrect. Although this view of the Port of Oakland is significant to Moss, nothing in the text describes the view as particularly energetic as opposed to calming, for example. Choice C is incorrect. The point of the text is that the view of the Port of Oakland from the subway train as it rises from underground is significant to Moss, not whether it is described as being correct, which the text does not address.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323052,"updateDate":1730147323052}$SATQ$::jsonb, 1730147323052, 1730147323052),
    ($SATQ$2d77660e$SATQ$, $SATQ$4b64bb5a-1640-497f-9cb4-24af67c229ba$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In the late 1800s, Spanish-language newspapers flourished in cities across Texas. San Antonio alone produced eleven newspapers in Spanish between 1890 and 1900. But El Paso surpassed all other cities in the state. This city produced twenty-two newspapers in Spanish during that period. El Paso is located on the border with Mexico and has always had a large population of Spanish speakers. Thus, it is unsurprising that this city became such a rich site for Spanish-language journalism.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"2f02d7f5-5ac4-48f5-a790-3e4a1ff8d229","content":"<p>To compare Spanish-language newspapers published in Texas today with ones published there during the late 1800s</p>"},{"id":"2b7c8906-f309-49e1-8fda-134cd0034238","content":"<p>To explain that Spanish-language newspapers thrived in Texas and especially in El Paso during the late 1800s</p>"},{"id":"72939f16-2173-42e8-991f-92175bf21900","content":"<p>To argue that Spanish-language newspapers published in El Paso influenced the ones published in San Antonio during the late 1800s</p>"},{"id":"3f32bd76-6ba3-4079-a220-f93be0b65353","content":"<p>To explain why Spanish-language newspapers published in Texas were so popular in Mexico during the late 1800s</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2b7c8906-f309-49e1-8fda-134cd0034238"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the main purpose of the text. The text begins by stating that there were many Spanish-language newspapers in cities across Texas in the late 1800s, citing San Antonio as a city that produced eleven such newspapers. The text then goes on to note that in El Paso, there were twenty-two newspapers published in Spanish in the late 1800s, more than any other Texas city. The text then concludes by explaining that the reason for this large number of Spanish-language newspapers was likely El Paso&rsquo;s location near Mexico and its large population of Spanish speakers. Therefore, the main purpose of the text is to explain that Spanish-language newspapers thrived in Texas cities, especially in El Paso, in the late 1800s.</p><p>Choice A is incorrect because the text doesn&rsquo;t discuss Spanish-language newspapers published in Texas today, let alone compare them with newspapers that were published in the 1800s. Choice C is incorrect. Although the text characterizes El Paso as a particularly rich site for Spanish-language journalism in the late 1800s, the text doesn&rsquo;t discuss whether newspapers published in El Paso influenced the newspapers published in other cities across Texas, including San Antonio. Choice D is incorrect because the text doesn&rsquo;t mention whether Spanish-language newspapers published in Texas were also widely read in Mexico. The text only focuses on the popularity of Spanish-language newspapers within Texas, and especially in El Paso.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2d77660e","external_id":"4b64bb5a-1640-497f-9cb4-24af67c229ba","vaultid":null,"uId":"a5519521-ef02-40ab-a805-e6af602b98f1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In the late 1800s, Spanish-language newspapers flourished in cities across Texas. San Antonio alone produced eleven newspapers in Spanish between 1890 and 1900. But El Paso surpassed all other cities in the state. This city produced twenty-two newspapers in Spanish during that period. El Paso is located on the border with Mexico and has always had a large population of Spanish speakers. Thus, it is unsurprising that this city became such a rich site for Spanish-language journalism.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"2f02d7f5-5ac4-48f5-a790-3e4a1ff8d229","content":"<p>To compare Spanish-language newspapers published in Texas today with ones published there during the late 1800s</p>"},{"id":"2b7c8906-f309-49e1-8fda-134cd0034238","content":"<p>To explain that Spanish-language newspapers thrived in Texas and especially in El Paso during the late 1800s</p>"},{"id":"72939f16-2173-42e8-991f-92175bf21900","content":"<p>To argue that Spanish-language newspapers published in El Paso influenced the ones published in San Antonio during the late 1800s</p>"},{"id":"3f32bd76-6ba3-4079-a220-f93be0b65353","content":"<p>To explain why Spanish-language newspapers published in Texas were so popular in Mexico during the late 1800s</p>"}],"keys":["2b7c8906-f309-49e1-8fda-134cd0034238"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the main purpose of the text. The text begins by stating that there were many Spanish-language newspapers in cities across Texas in the late 1800s, citing San Antonio as a city that produced eleven such newspapers. The text then goes on to note that in El Paso, there were twenty-two newspapers published in Spanish in the late 1800s, more than any other Texas city. The text then concludes by explaining that the reason for this large number of Spanish-language newspapers was likely El Paso&rsquo;s location near Mexico and its large population of Spanish speakers. Therefore, the main purpose of the text is to explain that Spanish-language newspapers thrived in Texas cities, especially in El Paso, in the late 1800s.</p><p>Choice A is incorrect because the text doesn&rsquo;t discuss Spanish-language newspapers published in Texas today, let alone compare them with newspapers that were published in the 1800s. Choice C is incorrect. Although the text characterizes El Paso as a particularly rich site for Spanish-language journalism in the late 1800s, the text doesn&rsquo;t discuss whether newspapers published in El Paso influenced the newspapers published in other cities across Texas, including San Antonio. Choice D is incorrect because the text doesn&rsquo;t mention whether Spanish-language newspapers published in Texas were also widely read in Mexico. The text only focuses on the popularity of Spanish-language newspapers within Texas, and especially in El Paso.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323036,"updateDate":1730147323036}$SATQ$::jsonb, 1730147323036, 1730147323036),
    ($SATQ$2e744883$SATQ$, $SATQ$80a9df22-3265-4910-8184-697981cf744e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Historians have argued that a crucial component of the Civil Rights Movement&rsquo;s success in the 1960s was the Southern Christian Leadership Conference&rsquo;s Citizen Education Program (CEP), which invited promising activists from across the South to its one-week training sessions in Dorchester, Georgia. Led by experienced organizers such as Dorothy Cotton and Septima Clark, CEP attendees<span style="text-decoration: underline;" role="region" aria-label="Referenced Content">&mdash;more than 7,000 in all&mdash;</span>participated in workshops on topics ranging from public speaking to legal doctrine before returning home and using their newly acquired knowledge to spearhead local civil rights initiatives.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"4945acf4-5b1e-4754-abf1-7074dcc206f5","content":"<p>It underscores the extent of the CEP&rsquo;s impact on the Civil Rights Movement of the 1960s.</p>"},{"id":"2ac0d540-a3f7-4d32-89ab-aac70a6a5a41","content":"<p>It illustrates the CEP organizers&rsquo; efforts to educate participants on a wide variety of topics.</p>"},{"id":"210a6861-fad2-41fd-8a68-c1ae2a56664f","content":"<p>It suggests that CEP attendees held a diverse array of opinions about the Southern Christian Leadership Conference&rsquo;s political philosophy.&nbsp;</p>"},{"id":"1b02c5ad-8967-4f02-8e0f-ba18c49f61fc","content":"<p>It establishes that criticism of the CEP was limited to a few individuals in the Southern Christian Leadership Conference.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["4945acf4-5b1e-4754-abf1-7074dcc206f5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first sentence of the text states that the CEP had a positive impact on the Civil Rights Movement in the 1960s. The next sentence explains that the CEP organized workshops for attendees, who later used the knowledge they gained to lead civil rights initiatives. And the underlined portion indicates the number of activists&mdash;more than 7,000&mdash;who participated in the workshops. Thus, the underlined portion provides a number that underscores the extent of the CEP&rsquo;s impact on the Civil Rights Movement in the 1960s.</p><p>Choice B is incorrect. Although the sentence that contains the underlined portion mentions some CEP workshop topics, the underlined portion itself addresses the number of participants in the CEP workshops, not the number of topics covered. Choice C is incorrect. Although the underlined portion refers to attendees of the CEP workshops, nothing in the underlined portion or the text as a whole addresses the Southern Christian Leadership Conference&rsquo;s philosophy or the attendees&rsquo; opinions thereof. Choice D is incorrect because neither the underlined portion nor the text as a whole mentions any criticism of the CEP by members of the Southern Christian Leadership Conference.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2e744883","external_id":"80a9df22-3265-4910-8184-697981cf744e","vaultid":null,"uId":"5313f490-da70-4092-a7f7-924b356ff26f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Historians have argued that a crucial component of the Civil Rights Movement&rsquo;s success in the 1960s was the Southern Christian Leadership Conference&rsquo;s Citizen Education Program (CEP), which invited promising activists from across the South to its one-week training sessions in Dorchester, Georgia. Led by experienced organizers such as Dorothy Cotton and Septima Clark, CEP attendees<span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">&mdash;more than 7,000 in all&mdash;</span>participated in workshops on topics ranging from public speaking to legal doctrine before returning home and using their newly acquired knowledge to spearhead local civil rights initiatives.</p>","stem":"<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"4945acf4-5b1e-4754-abf1-7074dcc206f5","content":"<p>It underscores the extent of the CEP&rsquo;s impact on the Civil Rights Movement of the 1960s.</p>"},{"id":"2ac0d540-a3f7-4d32-89ab-aac70a6a5a41","content":"<p>It illustrates the CEP organizers&rsquo; efforts to educate participants on a wide variety of topics.</p>"},{"id":"210a6861-fad2-41fd-8a68-c1ae2a56664f","content":"<p>It suggests that CEP attendees held a diverse array of opinions about the Southern Christian Leadership Conference&rsquo;s political philosophy.&nbsp;</p>"},{"id":"1b02c5ad-8967-4f02-8e0f-ba18c49f61fc","content":"<p>It establishes that criticism of the CEP was limited to a few individuals in the Southern Christian Leadership Conference.</p>"}],"keys":["4945acf4-5b1e-4754-abf1-7074dcc206f5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first sentence of the text states that the CEP had a positive impact on the Civil Rights Movement in the 1960s. The next sentence explains that the CEP organized workshops for attendees, who later used the knowledge they gained to lead civil rights initiatives. And the underlined portion indicates the number of activists&mdash;more than 7,000&mdash;who participated in the workshops. Thus, the underlined portion provides a number that underscores the extent of the CEP&rsquo;s impact on the Civil Rights Movement in the 1960s.</p><p>Choice B is incorrect. Although the sentence that contains the underlined portion mentions some CEP workshop topics, the underlined portion itself addresses the number of participants in the CEP workshops, not the number of topics covered. Choice C is incorrect. Although the underlined portion refers to attendees of the CEP workshops, nothing in the underlined portion or the text as a whole addresses the Southern Christian Leadership Conference&rsquo;s philosophy or the attendees&rsquo; opinions thereof. Choice D is incorrect because neither the underlined portion nor the text as a whole mentions any criticism of the CEP by members of the Southern Christian Leadership Conference.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$2e8ab360$SATQ$, $SATQ$11ddc0d9-49ae-4f5e-a32c-7c8aaabe8ddd$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Eighteenth-century historian Edward Gibbon thought the only character defect of the Roman emperor Marcus Aurelius was his mild temperament&mdash;though the emperor was widely considered virtuous, his overly permissive nature led him to <span aria-hidden="true">______</span><span class="sr-only">blank</span> the vices of those who surrounded him.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"3ac28d95-e96e-4dd4-9776-9abdd150a3bd","content":"<p>indulge</p>"},{"id":"d5a4f734-1868-4919-85e4-f88850b1bc0b","content":"<p>despise</p>"},{"id":"c6feda29-19b7-4755-8223-93d2e322f8c0","content":"<p>moderate</p>"},{"id":"cceed417-0eaf-4993-9ee0-72bc0b68abe2","content":"<p>criticize</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["3ac28d95-e96e-4dd4-9776-9abdd150a3bd"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the Roman emperor Marcus Aurelius. In this context, "indulge" means treat with excessive leniency. The text states that according to historian Edward Gibbon, Marcus Aurelius, who was widely considered virtuous, had only a single character flaw: his mild temperament. The text suggests that because of this flaw, Marcus Aurelius had an overly permissive nature. This context, in turn, supports the idea that Marcus Aurelius treated the vices, or evils, of those around him with excessive leniency, indulging rather than punishing those vices.</p><p>Choice B is incorrect. While the text does state that Marcus Aurelius was widely considered virtuous, it gives no indication that he was inclined to "despise," or hate, others&rsquo; vices. Rather, the text suggests that he showed undue tolerance for these vices because of his overly permissive nature&mdash;that is, his inclination to allow others to do as they wished. Choice C is incorrect because the text&rsquo;s description of Marcus Aurelius as overly permissive suggests that he showed undue tolerance for others&rsquo; vices, not that he tried to "moderate" those vices, or lessen their intensity. Choice D is incorrect because the text&rsquo;s description of Marcus Aurelius as overly permissive suggests that he showed undue tolerance for others&rsquo; vices, not that he attempted to "criticize," or speak disapprovingly of, those vices.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2e8ab360","external_id":"11ddc0d9-49ae-4f5e-a32c-7c8aaabe8ddd","vaultid":null,"uId":"7c1d9b90-2c67-4f06-ace2-4e9258e29637","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Eighteenth-century historian Edward Gibbon thought the only character defect of the Roman emperor Marcus Aurelius was his mild temperament&mdash;though the emperor was widely considered virtuous, his overly permissive nature led him to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the vices of those who surrounded him.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"3ac28d95-e96e-4dd4-9776-9abdd150a3bd","content":"<p>indulge</p>"},{"id":"d5a4f734-1868-4919-85e4-f88850b1bc0b","content":"<p>despise</p>"},{"id":"c6feda29-19b7-4755-8223-93d2e322f8c0","content":"<p>moderate</p>"},{"id":"cceed417-0eaf-4993-9ee0-72bc0b68abe2","content":"<p>criticize</p>"}],"keys":["3ac28d95-e96e-4dd4-9776-9abdd150a3bd"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the Roman emperor Marcus Aurelius. In this context, \"indulge\" means treat with excessive leniency. The text states that according to historian Edward Gibbon, Marcus Aurelius, who was widely considered virtuous, had only a single character flaw: his mild temperament. The text suggests that because of this flaw, Marcus Aurelius had an overly permissive nature. This context, in turn, supports the idea that Marcus Aurelius treated the vices, or evils, of those around him with excessive leniency, indulging rather than punishing those vices.</p><p>Choice B is incorrect. While the text does state that Marcus Aurelius was widely considered virtuous, it gives no indication that he was inclined to \"despise,\" or hate, others&rsquo; vices. Rather, the text suggests that he showed undue tolerance for these vices because of his overly permissive nature&mdash;that is, his inclination to allow others to do as they wished. Choice C is incorrect because the text&rsquo;s description of Marcus Aurelius as overly permissive suggests that he showed undue tolerance for others&rsquo; vices, not that he tried to \"moderate\" those vices, or lessen their intensity. Choice D is incorrect because the text&rsquo;s description of Marcus Aurelius as overly permissive suggests that he showed undue tolerance for others&rsquo; vices, not that he attempted to \"criticize,\" or speak disapprovingly of, those vices.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$3118ca93$SATQ$, $SATQ$23e6fdc3-ab8c-46ea-8898-6152e4bf95fb$SATQ$::uuid, $SATQ$e4e5fe5f-51d4-4764-95e3-d9a20432d88c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The fashion resale market, in which consumers purchase secondhand clothing from stores and online sellers, generated nearly $30 billion globally in 2019. Expecting to see continued growth, some analysts <span aria-hidden="true">______</span><span class="sr-only">blank</span> that revenues will more than double by 2028. </p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"468baff5-bdca-4739-87a4-7b6702d92c59","content":"<p>produced</p>"},{"id":"7d9d1743-1762-4411-b5fa-41f5f01e8769","content":"<p>denied</p>"},{"id":"700eba34-ad2a-4777-9002-dd99a68f5e9f","content":"<p>worried</p>"},{"id":"8415e452-37ca-46b2-a284-17a250a4b49d","content":"<p>predicted</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8415e452-37ca-46b2-a284-17a250a4b49d"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the fashion resale market&rsquo;s continued growth. As used in this context, &ldquo;predicted&rdquo; means forecast, or indicated that something would happen in the future. The text indicates that the fashion resale market made a lot of money in 2019 and that some analysts expected the market to continue to grow. This context suggests that the analysts believed that the fashion resale market was going to make more money than it had already made, with the analysts indicating that revenues would more than double by 2028. </p><p>Choice A is incorrect because it wouldn&rsquo;t make sense in context to say that some analysts &ldquo;produced,&rdquo; or manufactured or brought about, the increase in future revenues of the fashion resale market. The analysts themselves couldn&rsquo;t have brought about the future revenue growth, since, as the text suggests, they were merely in the position of drawing conclusions about future fashion resale market revenue based on 2019 revenue. Choice B is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they &ldquo;denied,&rdquo; or rejected, this notion. Nothing in the text supports the idea that these analysts thought the revenues wouldn&rsquo;t grow. Choice C is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they &ldquo;worried,&rdquo; or felt concerned, that revenue would significantly increase by 2028. Nothing in the text suggests that the analysts felt concerned about the increase; rather, the text suggests that the increase would represent a favorable outcome, since it would mean that the fashion resale market grew to generate even more revenue. </p>$SATQ$, false, 0, $SATQ$OSP-967-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$816328df-f22d-422f-b1b7-697c06b068b1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"3118ca93","external_id":"23e6fdc3-ab8c-46ea-8898-6152e4bf95fb","vaultid":"e4e5fe5f-51d4-4764-95e3-d9a20432d88c","uId":"c8148841-ffcc-4abe-92e8-ca2112d1d3fb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The fashion resale market, in which consumers purchase secondhand clothing from stores and online sellers, generated nearly $30 billion globally in 2019. Expecting to see continued growth, some analysts <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that revenues will more than double by 2028. </p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"468baff5-bdca-4739-87a4-7b6702d92c59","content":"<p>produced</p>"},{"id":"7d9d1743-1762-4411-b5fa-41f5f01e8769","content":"<p>denied</p>"},{"id":"700eba34-ad2a-4777-9002-dd99a68f5e9f","content":"<p>worried</p>"},{"id":"8415e452-37ca-46b2-a284-17a250a4b49d","content":"<p>predicted</p>"}],"keys":["8415e452-37ca-46b2-a284-17a250a4b49d"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the fashion resale market&rsquo;s continued growth. As used in this context, &ldquo;predicted&rdquo; means forecast, or indicated that something would happen in the future. The text indicates that the fashion resale market made a lot of money in 2019 and that some analysts expected the market to continue to grow. This context suggests that the analysts believed that the fashion resale market was going to make more money than it had already made, with the analysts indicating that revenues would more than double by 2028. </p><p>Choice A is incorrect because it wouldn&rsquo;t make sense in context to say that some analysts &ldquo;produced,&rdquo; or manufactured or brought about, the increase in future revenues of the fashion resale market. The analysts themselves couldn&rsquo;t have brought about the future revenue growth, since, as the text suggests, they were merely in the position of drawing conclusions about future fashion resale market revenue based on 2019 revenue. Choice B is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they &ldquo;denied,&rdquo; or rejected, this notion. Nothing in the text supports the idea that these analysts thought the revenues wouldn&rsquo;t grow. Choice C is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they &ldquo;worried,&rdquo; or felt concerned, that revenue would significantly increase by 2028. Nothing in the text suggests that the analysts felt concerned about the increase; rather, the text suggests that the increase would represent a favorable outcome, since it would mean that the fashion resale market grew to generate even more revenue. </p>","parenttemplatename":"OSP-967-WIC","parenttemplateid":"","templateclusterid":"816328df-f22d-422f-b1b7-697c06b068b1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357)
